window.ZIKRA_CONTENT=window.ZIKRA_CONTENT||{};window.ZIKRA_CONTENT.ar=[{"id":2,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","title":"دعاء بعد الصلاة للرزق والمساعدة","source":"البخاري: ٨٤٤","reflection":"هذا الدعاء بعد الصلاة يذكرنا بأن الله وحده هو المتحكم في كل الثروات والنعم، مما يجعله طريقة قوية لطلب الرزق والمساعدة بعد كل صلاة فرض في الحياة اليومية.","lesson":"قول (اللهم لا مانع لما أعطيت) يجلب البركة في الرزق ويحفظ المال."},{"id":3,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","title":"فضل لا إله إلا الله (عتق رقبة)","source":"البخاري: ٦٤٠٤","reflection":"إن قول كلمة التوحيد يقرب المسلم من رحمة الله وقدرته، ويقوي القلوب ويملأ الحياة بالبركة من خلال هذا الدعاء الأعظم في الإسلام.","lesson":"كلمة التوحيد تمحو الكثير من الذنوب وتجلب البركة في كل عمل وفي كل يوم."},{"id":4,"text":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","title":"دعاء للهداية (تلاوة سورة الفاتحة)","source":"سورة الفاتحة ٥:١","reflection":"هذا الدعاء للهداية من سورة الفاتحة يساعد المسلمين على سؤال الله عز وجل العون والإرشاد، مما يجعل كل صلاة وعمل مليئاً بالأمل والثقة برحمته وحكمته.","lesson":"قول (إياك نعبد وإياك نستعين) يجلب الهداية الحقيقية في كل حياة مسلم."},{"id":5,"text":"اِهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُّسْتَقِيْمٍ","title":"الدعاء النبوي للهداية (صحيح مسلم)","source":"مسلم: ٧٧٠","reflection":"هذا الدعاء النبوي للهداية من صحيح مسلم يساعد المسلمين في العثور على الطريق الصحيح عندما يكون الحق غير واضح، مما يثبت القلوب بعون الله ومعاني التوحيد في الإسلام.","lesson":"الدعاء النبوي للهداية يقرب المسلمين من الصراط المستقيم دائماً."},{"id":6,"text":"اَللَّهُمَّ أَعِنِّيْ عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","title":"دعاء بعد الصلاة للعون على العبادة","source":"صحيح (الألباني). أبو داود: ١٥٢٢","reflection":"هذا الدعاء بعد الصلاة يساعد المسلمين على تذكر الله، وشكره، وأداء العبادة بأفضل طريقة، مما يجعل كل صلاة مليئة بالبركة والعمل الصالح للقلب.","lesson":"قول (اللهم أعني على ذكرك) يقوي الذكر ويجلب السلام بعد كل صلاة."},{"id":7,"text":"وَاهْدِنِيْ لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِيْ لِأَحْسَنِهَا إِلَّا أَنْتَ وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ","title":"دعاء لحسن الخلق (دعاء مسنون)","source":"مسلم: ٧٧١","reflection":"سؤال الله أحسن الأخلاق يجلب اللطف والاحترام في الحياة، ويحسن كل عمل، ويلين القلوب بهذا الدعاء المسنون لحسن الخلق والعمل اليومي.","lesson":"يهدي الله المسلم لأحسن الأخلاق بهذا الدعاء لحسن الخلق."},{"id":8,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالسَّدَادَ","title":"دعاء للهداية","source":"مسلم: ٢٧٢٥","reflection":"سؤال الله الهداية والقوة بهذا الدعاء يجلب النور للقلب، ويساعد المسلم على الثبات، ويبقي الإيمان قوياً في كل خطوة.","lesson":"الدعاء يوجه المسلم إلى الصراط المستقيم دائماً."},{"id":9,"text":"اَللَّهُمَّ اهْدِنِيْ فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ وَتَوَلَّنِيْ فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ وَلَا يَعِزُّ مَنْ عَادَيْتَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ","title":"صلاة ليلية قوية في الوتر (دعاء القنوت)","source":"صحيح (الألباني). أبو داود: ١٤٢٥","reflection":"يجلب دعاء القنوت في الوتر عون الله والبركة والأمان، ويقوي القلوب ويبقي المسلم قريباً من عناية الله كل ليلة.","lesson":"دعاء القنوت في صلاة الوتر يجلب هداية الله ويحافظ على الإيمان."},{"id":11,"text":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَىَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ","title":"دعاء للاستغفار (رب اغفر لي وتب علي إنك)","source":"صحيح (الألباني). أبو داود: ١٥١٦","reflection":"إن سؤال الله المغفرة بهذا الدعاء القصير يجلب الطمأنينة للقلب، ويساعد المسلم على تطهير عمله، ويبقي الأمل حياً في رحمة الله ولطفه كل يوم.","lesson":"دعاء (رب اغفر لي) يمحو الذنوب ويقرب رحمة الله إلى القلب."},{"id":12,"text":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَىُّ الْقَيُّوْمُ وَأَتُوبُ إِلَيْهِ","title":"دعاء للاستغفار من كبائر الذنوب","source":"صحيح (الألباني). الترمذي: ٣٥٧٧","reflection":"العودة إلى الله بهذا الدعاء يبعث الأمل، ويمحو الأخطاء الكبيرة، ويساعد المسلم على الشعور برحمة الله والبركة في كل جزء من حياته.","lesson":"دعاء أستغفر الله العظيم يزيل الذنوب الثقيلة ويجلب مغفرة الله."},{"id":13,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ","title":"دعاء للحماية من النار ودخول الجنة","source":"صحيح (الألباني). ابن ماجه: ٩١٠","reflection":"سؤال الله الجنة والسلامة من النار بهذا الدعاء يبعث الأمل، ويوجه القلوب نحو الآخرة، ويساعد المسلم على تذكر الهدف الحقيقي للحياة كل يوم.","lesson":"دعاء (اللهم إني أسألك) يعزز رغبة المسلم في الجنة في كل صلاة."},{"id":15,"text":"اَللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ","title":"دعاء للقلوب على الطاعة (صحيح مسلم)","source":"مسلم: ٢٦٥٥","reflection":"سؤال الله أن يهدي القلب بهذا الدعاء يجلب الهدوء، ويساعد المسلم على البقاء في الطريق الصحيح، ويبقي القلب قريباً من أوامر الله في كل جزء من حياته.","lesson":"قول (يا مقلب القلوب) يساعد القلوب على أن تبقى لينة ومستعدة لهداية الله."},{"id":16,"text":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِيْ عَلَى دِيْنِكَ","title":"دعاء للثبات على الدين (دعاء مسنون)","source":"صحيح (الألباني). الترمذي: ٣٥٢٢","reflection":"سؤال الله أن يثبت القلب على دينه بهذا الدعاء يساعد المسلم على التمسك بدينه، ويجلب الطمأنينة، ويحمي الإيمان من الشكوك وطرق الضلال كل يوم.","lesson":"دعاء (يا مقلب القلوب) يحافظ على ثبات القلب على الإسلام الحقيقي."},{"id":17,"text":"اَللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآَخِرَةِ","title":"دعاء للحماية في جميع الأمور (دعاء مسنون)","source":"صحيح (السيوطي). الجامع الصغير: ١٤٥٠","reflection":"سؤال الله حسن الخاتمة في كل أمر بهذا الدعاء يجلب الأمان، ويحفظ المسلم من الخزي، ويساعد القلب على الثقة بقضاء الله في الدنيا والآخرة.","lesson":"هذا الدعاء يحفظ المسلم من جميع أنواع الشرور."},{"id":18,"text":"اَللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ","title":"دعاء للنجاح في الدين (اللهم أصلح لي ديني)","source":"مسلم: ٢٧٢٠","reflection":"سؤال الله سبحانه بهذا الدعاء للنجاح يجلب العون في الدين والدنيا والآخرة، ويجعل حياة المسلم مليئة بالبركة، ويحسن كل يوم برحمة الله وعنايته.","lesson":"قول (اللهم أصلح لي ديني) يساعد في الحفاظ على قوة الدين وتجنب أخطاء العمل."},{"id":19,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ","title":"دعاء للحماية وطلب عون الله","source":"مسلم: ٢٧٣٩","reflection":"دعاء الحماية هذا يسأل الله أن يحفظ نعمه، ويحمي من الأذى، ويساعد كل مسلم على البقاء قوياً في أوقات الشدة والخوف.","lesson":"يعطي الله بركته ويحفظ النعم عند الدعاء بهذا الدعاء للحماية."},{"id":20,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","title":"دعاء للتوتر والقلق والاكتئاب","source":"البخاري: ٢٨٩٣","reflection":"هذا الدعاء للتوتر والحزن يساعد المسلم على إيجاد السلام والقوة والراحة من المشاعر الثقيلة، ونسأل فيه الله أن يزيل الهموم والديون وكل أنواع الشدائد من الحياة.","lesson":"يزيل الله الحزن ويمنح السلام عند الدعاء بهذا الدعاء للتوتر بإيمان."},{"id":22,"text":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","title":"دعاء للاستغفار من الذنوب","source":"البخاري: ٦٤٠٥","reflection":"دعاء الاستغفار هذا يجلب رحمة الله، ويمحو الأخطاء، ويملأ القلب بالبركة والسكينة لكل مسلم يقوله بإيمان.","lesson":"يغفر الله الكثير من الذنوب عندما يسبح المسلم بـ (سبحان الله وبحمده)."},{"id":23,"text":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ","title":"ذكر للاستغفار (دعاء سبحان الله وبحمده)","source":"البخاري: ٦٤٠٦","reflection":"هذا الذكر والدعاء يجلب مغفرة الله، ويملأ القلب بالبركة، ويجعل عمل كل مسلم يضيء ببركات تسبيح عظمة الله ورحمته.","lesson":"يغفر الله الكثير من الذنوب عندما يقول المسلم سبحان الله وبحمده سبحان الله العظيم."},{"id":24,"text":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ","title":"ذكر متين أحبه الله (دعاء مسنون)","source":"[١] مسلم: ٢١٣٧\n[٢] مسلم: ٢٦٩٥","reflection":"هذا الذكر المتين يقرب القلوب من الله ويملأ الحياة بالبركة، فهذه الكلمات يحبها الله ويسهل على كل مسلم قولها في أي وقت.","lesson":"قول سبحان الله والحمد لله ولا إله إلا الله والله أكبر يجلب ثواباً عظيماً من الله ويقوي الإيمان."},{"id":25,"text":"سُبْحَانَ اللَّهِ","title":"فوائد قول سبحان الله","source":"مسلم: ٢٦٩٨","reflection":"قول (سبحان الله) يقرب المسلم من حب الله ومغفرته، ويطهر القلوب ويملأ كل مساء بالسلام والبركات من أفضل الأذكار.","lesson":"قول (سبحان الله) يمحو صغار الذنوب ويجلب البركة في العمل."},{"id":26,"text":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ هُوَ اللَّـهُ أَحَدٌ ﴿١﴾ اللَّـهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ﴿٤﴾","title":"فوائد قراءة سورة الإخلاص يومياً","source":"صحيح (الألباني). صحيح الجامع: ٦٤٧٢","reflection":"تجلب سورة الإخلاص ثواباً عظيماً وتقوي الإيمان، فهذه السورة القصيرة تعادل ثلث القرآن وتملأ القلب بحب الله كل يوم.","lesson":"سورة الإخلاص تمنحك ثواباً يعادل قراءة ثلث القرآن."},{"id":27,"text":"سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ","title":"دعاء يومي لغرس شجرة في الجنة","source":"صحيح (الألباني). الترمذي: ٣٤٦٤","reflection":"هذا الدعاء للجنة يساعد المسلم على نيل أشجار في الجنة، ويقرب حمد الله ورحمته، ويجعل كل يوم مليئاً بالأمل والثواب للآخرة.","lesson":"قول سبحان الله العظيم وبحمده يغرس شجرة في الجنة."},{"id":28,"text":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","title":"دعاء للجنة (لا حول ولا قوة)","source":"البخاري: ٦٣٨٤","reflection":"يذكر دعاء الجنة كل مسلم بأن القوة كلها من الله وحده، مما يجلب الأمل، والثواب، والعون في كل وقت عصيب لمن يتوكل على قوته.","lesson":"لا حول ولا قوة إلا بالله تفتح أبواب الجنة للمسلمين."},{"id":29,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَزِيزِ الْحَكِيمِ","title":"دعاء الحمد لله (دعاء مسنون)","source":"مسلم: ٢٦٩٦","reflection":"هذا الدعاء لحمد الله يقرب المسلم إليه، ويملأ القلب بالشكر ويذكرنا بعظمة الله ورحمته وقدرته في كل جزء من حياتنا اليومية.","lesson":"عون الله يأتي لمن يقول (لا إله إلا الله) بكامل الإيمان."},{"id":30,"text":"اَللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي","title":"دعاء بعد اعتناق الإسلام (دعاء مسنون)","source":"مسلم: ٢٦٩٧","reflection":"هذا الدعاء بعد اعتناق الإسلام يساعد المسلم الجديد على سؤال الله المغفرة، والرحمة، والهداية، والعافية، والرزق، مما يجعل بداية رحلته الإيمانية مليئة بالأمل والبركة.","lesson":"(اللهم اغفر لي وارحمني) تجلب مغفرة الله وتمحو الذنوب القديمة."},{"id":31,"text":"اَلْحَمْدُ لِلَّهِ","title":"أعظم ذكر ودعاء في الإسلام","source":"حسن (الألباني). الترمذي: ٣٣٨٣","reflection":"قول (الحمد لله) يملأ القلب بالشكر، ويجلب السكينة، ويبقي المسلم قريباً من الله، مما يجعل كل لحظة مليئة بالبركة والأمل في الحياة اليومية.","lesson":"معنى (الحمد لله) يعلم المسلم أن يشكر الله في كل عمل."},{"id":32,"text":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","title":"ذكر متين يدوم إلى الأبد في الجنة","source":"مسند أحمد (رقم: ٥١٣) (بتحقيق أحمد شاكر) وإسناده صحيح. انظر مجمع الزوائد ١/٢٩٧. وذكره ابن حجر في بلوغ المرام وقال صححه ابن حبان والحاكم.","reflection":"هذا الذكر والدعاء يملأ القلب بالإيمان، ويجلب رحمة الله، ويعطي ثواباً يدوم في الجنة للأبد، مما يجعل عمل كل مسلم قوياً ومليئاً بالبركة.","lesson":"معنى (سبحان الله) يساعد المسلم على الحفاظ على لسانه نقياً بذكر الله."},{"id":36,"text":"إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ ﴿١﴾ وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ ﴿٢﴾ لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ ﴿٣﴾ تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ ﴿٤﴾ سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ ﴿٥﴾","title":"فضل سورة القدر","source":"سورة القدر ٩٧:١-٥","reflection":"تخبر سورة القدر عن ليلة القدر، وتجلب الثواب العظيم والسلام والبركات للمسلمين الذين يقرؤون ويؤمنون برسالتها، مما يجعل كل ليلة من رمضان مليئة بالأمل.","lesson":"سورة القدر تجلب ثواباً خيراً من ألف شهر من العمل."},{"id":37,"text":"اَللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","title":"دعاء ليلة القدر للمغفرة","source":"صحيح (الألباني). الترمذي: ٣٥١٣","reflection":"في ليلة القدر المباركة، يجلب دعاء المغفرة هذا الأمل والرحمة، ويساعد كل مسلم على طلب العفو والبركة في العشر الأواخر من رمضان.","lesson":"رحمة الله تغمر قلب المسلم الذي يدعو بدعاء ليلة القدر."},{"id":39,"text":"كَانُوا قَلِيلًا مِّنَ اللَّيْلِ مَا يَهْجَعُونَ ﴿١٧﴾ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ ﴿١٨﴾","title":"دعاء الاستغفار في وقت التهجد","source":"[١] البخاري: ١١٤٥\n[٢] سورة الذاريات ٥١: ١٧-١٨","reflection":"","lesson":""},{"id":45,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ‏ اَلْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","title":"الدعاء عند الاستيقاظ في الليل (دعاء مسنون)","source":"البخاري: ١١٥٤","reflection":"هذا الدعاء في الليل يملأ القلب بحمد الله وقوته، ويساعد المسلمين على ذكره بعد النوم ويجلب السلام والبركة في الساعات الهادئة قبل الفجر.","lesson":"عون الله يقترب لمن يدعو عند الاستيقاظ في الليل."},{"id":46,"text":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِيْنَ","title":"دعاء يونس (لا إله إلا أنت سبحانك)","source":"صحيح (الألباني). الترمذي: ٣٥٠٥","reflection":"هذا الدعاء ليونس يجلب الأمل، والفرج للمسلمين الذين يواجهون الصعاب، ويساعد القلوب في العثور على رحمة الله والمغفرة في أوقات الشدة والكرب.","lesson":"الله يزيل الشدائد لمن يدعو بدعاء يونس في الأوقات الصعبة."},{"id":47,"text":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ، اَللَّهُمَّ أْجُرْنِيْ فِي مُصِيْبَتِيْ وَأَخْلِفْ لِي خَيْرًا مِّنْهَا","title":"دعاء الشدائد (دعاء مسنون)","source":"مسلم: ٩١٨","reflection":"هذا الدعاء للشدائد يساعد المسلمين على إيجاد الأمل والصبر في الأوقات الصعبة، حيث يسألون الله الثواب والبديل الأفضل بعد كل ابتلاء أو فقد.","lesson":"يمنح الله الصبر والأجر لمن يدعو بدعاء الشدائد عند المصيبة."},{"id":49,"text":"اَللَّهُ أَكْبَرُ كَبِيْرًا وَالْحَمْدُ لِلَّهِ كَثِيْرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيْلًا","title":"الدعاء قبل بدء الصلاة","source":"مسلم: ٦٠١","reflection":"هذا الدعاء قبل الصلاة يملأ القلب بحمد الله، مما يساعد المسلمين على بدء صلاتهم بالبركة والتركيز القوي على الإيمان والعمل.","lesson":"(الله أكبر كبيرا والحمد لله كثيرا) تمنح السلام قبل كل صلاة."},{"id":50,"text":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيْرًا طَيِّبًا مُبَارَكًا فِيهِ","title":"دعاء الاستفتاح في الصلاة","source":"","reflection":"دعاء الاستفتاح هذا يملأ القلب بحمد الله والبركة، ويجعل بداية كل صلاة ممتلئة بالحمد وبذهن صافٍ مهيأ للعبادة.","lesson":"يهب الله المزيد من البركة في الصلاة عندما يبدأ المسلمون بدعاء الاستفتاح."},{"id":52,"text":"رَبَّنَا وَلَكَ الْحَمْدُ، حَمْدًا كَثِيْرًا طَيِّبًا مُبَارَكًا فِيهِ","title":"الدعاء بعد الركوع (ربنا ولك الحمد)","source":"البخاري: ٧٩٩","reflection":"هذا الدعاء بعد الركوع يملأ صلاتك بالحمد والشكر، ويجلب لك المزيد من البركة والقرب من الله، ويقوي صلاتك بكل كلمة تقولها من قلبك.","lesson":"يمنح الله المزيد من البركة في الصلاة عندما يقول المسلم (ربنا ولك الحمد) بعد الركوع."},{"id":54,"text":"اَللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ","title":"الدعاء بعد الركوع (ربنا ولك الحمد)","source":"البخاري: ٧٩٦","reflection":"هذا الدعاء بعد الركوع يجلب المزيد من الحمد لله في الصلاة، مما يجعل كل ركعة مليئة بالشكر والبركة، ويساعد المسلمين في الحفاظ على صلاتهم قوية وقريبة من السنة.","lesson":"يحب الله أن يقول المسلمون (ربنا ولك الحمد) بعد الركوع في كل صلاة."},{"id":55,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","title":"الدعاء قبل السلام","source":"صحيح (الألباني). النسائي: ١٣٠١","reflection":"هذا الدعاء قبل إنهاء الصلاة يجلب الأمل في المغفرة والرحمة، مما يتيح لكل مسلم سؤال الله بأسمائه الحسنى وإيجاد السكينة في قلبه قبل التسليم.","lesson":"يغفر الله الذنوب عندما يدعو المسلم بهذا الدعاء قبل السلام بقلب صادق في الصلاة."},{"id":56,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّوْمُ","title":"الدعاء قبل السلام","source":"صحيح (الألباني). أبو داود: ١٤٩٥","reflection":"هذا الدعاء بعد التشهد يملأ القلب بحمد الله، مما يقوي الصلاة ويجلب الأمل في عونه ورحمته وبركته قبل التسليم في كل صلاة.","lesson":"يمنح الله المزيد من البركة في الصلاة عندما يقرأ المسلمون هذا الدعاء بعد التشهد."},{"id":57,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ اَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","title":"الدعاء بعد التشهد (الدعاء قبل السلام)","source":"صحيح (الألباني). أبو داود: ١٤٩٣","reflection":"الدعاء بعد التشهد يجعل الصلاة أقوى بحمد الله وتوحيده، مما يساعد المسلمين على طلب كل ما يحتاجون إليه بقلب طاهر قبل التسليم.","lesson":"(اللهم إني أسألك) في هذا الدعاء تجلب المزيد من البركة في الصلاة."},{"id":58,"text":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","title":"الدعاء بعد الوضوء","source":"مسلم: ٢٣٤","reflection":"الدعاء بعد الوضوء يقرب المسلم إلى الله، مما يجعل الوضوء مميزاً ومليئاً بالبركة، مع الحفاظ على القلب نقياً والإيمان قوياً للعبادة.","lesson":"يفتح الله أبواب الجنة الثمانية لمن يقرأ هذا الدعاء بعد الوضوء."},{"id":59,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ","title":"دعاء يوم عرفة","source":"حسن (الألباني). الترمذي: ٣٥٨٥","reflection":"هذا الدعاء في يوم عرفة يقرب المسلم من رحمة الله، ليملأ قلبه بالأمل والبركة، بينما يستمر اللسان بأفضل الأذكار وحمد الله.","lesson":"يغفر الله العديد من الذنوب لمن يدعو بهذا الدعاء يوم عرفة."},{"id":68,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيْرٌ‏.‏ اَلْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","title":"الدعاء بعد الاستيقاظ في الليل (لا إله إلا الله وحده)","source":"البخاري: ١١٥٤","reflection":"هذا الدعاء بعد الاستيقاظ في الليل يملأ القلب بحمد الله ويجلب البركة، مما يجعل الليل هادئاً ويقوي الإيمان لكل مسلم يذكر الله في الساعات الهادئة.","lesson":"يمنح الله ثواباً خاصاً للمسلم الذي يقول (لا إله إلا الله) بعد الاستيقاظ."},{"id":72,"text":"لَا إِلَهَ إِلَّآ أَنتَ سُبْحٰنَكَ إِنِّى كُنْتُ مِنَ الظّٰلِمِينَ","title":"دعاء يونس (لا إله إلا أنت سبحانك)","source":"صحيح (الألباني). الترمذي: ٣٥٠٥","reflection":"هذا الدعاء ليونس يجلب الأمل والمغفرة لكل مسلم، ويساعد القلوب على إيجاد السكينة والبركة، ويسهل سؤال الله العون في أوقات الشدة والحزن.","lesson":"يزيل الله المتاعب الكبيرة لمن يدعو بدعاء يونس بقلب صادق."},{"id":73,"text":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ اَللَّهُمَّ أْجُرْنِيْ فِي مُصِيْبَتِيْ وَأَخْلِفْ لِي خَيْرًا مِّنْهَا","title":"دعاء المحن والشدائد","source":"مسلم: ٩١٨","reflection":"هذا الدعاء في المحن والمصائب يساعد المسلم على إيجاد السلام والصبر، ويجلب الأمل والبركة من الله عندما تثقل الحياة وتكون القلوب بحاجة للسلوان في الأوقات الفصيبة.","lesson":"يمنح الله أشياء أفضل لمن يقول (إنا لله وإنا إليه راجعون)."},{"id":74,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","title":"الدعاء باسم الله الأعظم (الاسم الأعظم)","source":"صحيح (الألباني). النسائي: ١٣٠٠","reflection":"هذا الدعاء بأسماء الله يقرب المؤمن إلى رحمة الله وعونه، ويفتح أبواب البركة ويقوي القلب بالإيمان والأمل في كل أمور الحياة.","lesson":"يستجيب الله الدعاء بأسمائه بسرعة عندما يدعو المسلم بإيمان كامل."},{"id":75,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّوْمُ","title":"الدعاء بعد التشهد (اللهم إني أسألك)","source":"صحيح (الألباني). النسائي: ١٣٠٠","reflection":"هذا الدعاء بعد التشهد يقرب المسلم من رحمة الله وعونه، ويجعل كل صلاة مليئة بالبركة والأمل من خلال دعاء الله بأسمائه الحسنى وحمده.","lesson":"(اللهم إني أسألك) في التشهد تجعل الدعاء بعد الصلاة أكثر قبولاً."},{"id":78,"text":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَسُوْءِ الْكِبَرِ، رَبِّ أَعُوْذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ","title":"دعاء الصباح للحماية والبركات","source":"","reflection":"ابدأ يومك بهذا الدعاء الصباحي لتقريب بركة الله، طالباً الأشياء الجيدة والسلامة من الأذى، مما يجعل كل صباح مليئاً بالأمل والبركة للمسلم.","lesson":"(أصبحنا وأصبح الملك لله) تحفظ القلب آمناً من الشيطان والشر."},{"id":79,"text":"أَمْسَيْنَا وَأَمْسَا الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَسُوْءِ الْكِبَرِ، رَبِّ أَعُوْذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ","title":"دعاء المساء المسنون الذي كان يقرؤه النبي ﷺ","source":"مسلم: ٢٧٢٣","reflection":"دعاء المساء هذا هو درع للمسلمين، يسأل الله البركة والحماية من الشر، والبركات في الليل، تماماً كما كان يفعل النبي صلى الله عليه وسلم، مما يجلب السلام والأمان للقلب قبل النوم.","lesson":"عند غروب الشمس، اقرأ دعاء المساء للحماية والبركات مع بداية الليل."},{"id":80,"text":"اَللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ","title":"دعاء الصباح للحماية (أذكار الصباح)","source":"","reflection":"ابدأ يومك بهذا الدعاء الصباحي للحماية، طالباً من الله أن يحفظك، ويجلب لك البركة، ويهدي قلبك برحمته من الفجر حتى الليل.","lesson":"(اللهم) في دعاء الصباح هذا تجلب الحفظ والطمأنينة لقلب المسلم."},{"id":81,"text":"اَللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ","title":"أدعية المساء (دعاء مسنون)","source":"صحيح (الألباني). أبو داود: ٥٠٦٨","reflection":"جِد السلام والأمان مع غروب الشمس بالدعاء بهذا الدعاء المسائي، طالباً من الله أن يبقي إيمانك قوياً وعائلتك آمنة برحمته وبركاته كل ليلة.","lesson":"(اللهم) في دعاء المساء تجلب الحفظ والسكينة للقلب ليلاً."},{"id":82,"text":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اَللَّهُـمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ فَتْحَهُ، وَنَصْرَهُ، وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ","title":"دعاء الصباح للبركات والحماية","source":"","reflection":"ابدأ يومك بهذا الدعاء الصباحي، طالباً من الله البركة، والعون، والسلامة، ليبقى قلبك قوياً ويزداد عملك نوراً وهداية من الفجر حتى الليل.","lesson":"(أصبحنا وأصبح الملك لله) تجلب البركة والنور في كل صباح جديد."},{"id":83,"text":"أَمْسَيْنَا وَأَمْسَا الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُـمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ :فَتْحَهَا، وَنَصْرَهَا، وَنُورَهَا، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيهَا وَشَرِّ مَا بَعْدَهَا","title":"دعاء المساء للهداية والبركات","source":"","reflection":"اختم يومك بهذا الدعاء المسائي للهداية والبركة، طالباً من الله أن يملأ ليلتك بالبركة، والأمان، والنور، وأن يبقي قلبك قريباً منه حتى الصباح.","lesson":"(أمسينا وأمسى الملك لله) تجلب البركة والسلام في كل ليلة."},{"id":84,"text":"أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ","title":"دعاء الصباح للفطرة الإسلامية (دعاء مسنون)","source":"","reflection":"ابدأ يومك بهذا الدعاء الصباحي، طالباً من الله أن يبقي إيمانك قوياً، وقلبك على طريق الإسلام، وعملك نقياً كالنبي إبراهيم والنبي محمد صلى الله عليهما وسلم.","lesson":"(أصبحنا على فطرة الإسلام) تبقي المسلم ثابتاً على دين الإسلام كل صباح."},{"id":85,"text":"أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ","title":"دعاء المساء للإيمان (دعاء مسنون)","source":"صحيح (الألباني). صحيح الجامع: ٤٦٧٤","reflection":"هذا الدعاء المسائي يساعد المسلم على إبقاء إيمانه قوياً ونقياً، ويذكرنا بطريق محمد والنبي إبراهيم، ويجلب السلام والبركة للقلب كل مساء.","lesson":"يعطي الله البركة لمن يدعو بهذا الدعاء المسائي بإيمان صادق."},{"id":86,"text":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","title":"دعاء الاستغفار للذنوب في الصباح والمساء","source":"البخاري: ٦٣٠٧، مسلم: ٢٧٠٢","reflection":"أذكار الصباح والمساء هذه تقرب المسلم من رحمة الله، وتساعد القلوب على البقاء نقية ومفعمة بالأمل من خلال الاستغفار والتوبة إليه توبة صادقة كل يوم.","lesson":"يغفر الله ذنوب من يقول دعاء الاستغفار هذا في أذكار الصباح والمساء."},{"id":87,"text":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَى نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ","title":"دعاء سبحان الله وبحمده (دعاء الصباح)","source":"مسلم: ٢٧٢٦","reflection":"دعاء الصباح هذا يملأ القلب بحمد الله، ويجلب الطمأنينة والبركة، ويساعد المسلم على تذكر عظمته ورحمته منذ بداية اليوم.","lesson":"(سبحان الله وبحمده) تجلب بركة لا حصر لها للمسلم في الصباح."},{"id":88,"text":"اَللَّھُمَّ صَلِّ عَلَی مُحَمَّدٍ وَّعَلَی آلِ مُحَمَّدٍ کَمَا صَلَّیْتَ عَلَی اِبْرَاھِیْمَ وَعَلَی آلِ اِبْرَاھِیْمَ اِنَّكَ حَمِیْدٌ مَّجِیْدٌ، اَللَّھُمَّ بَارِكْ عَلَی مُحَمَّدٍ وَّعَلَی آلِ مُحَمَّدٍ کَمَا بَارَکْتَ عَلَی اِبْرَاھِیْمَ وَعَلَی آلِ اِبْرَاھِیْمَ اِنَّكَ حَمِیْدٌ مَّجِیْدٌ","title":"دعاء الصباح والمساء (الصلاة الإبراهيمية)","source":"الطبراني، صحيح الترغيب والترهيب ١/٢٧٣","reflection":"تُحل الصلاة الإبراهيمية البركات على القلب والمنزل، لتجعل كل صباح ومساء ممتلئاً بالبركة، ومحبة محمد، والقرب من رحمة الله.","lesson":"يجلب الدعاء بالصلاة الإبراهيمية بركة الله لمن يدعو بها في الصباح والمساء."},{"id":89,"text":"بِسْمِ اللَّهِ الَّذِيْ لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ","title":"دعاء الصباح والمساء للحماية","source":"صحيح (الألباني). أبو داود: ٥٠٨٨","reflection":"هذا الدعاء للحماية من الأذى يبقي المسلم آمناً باسم الله، مما يجعل كل صباح ومساء مليئاً بالسلام، والأمان، والتوكل على قدرته وعلمه.","lesson":"(بسم الله) تبعد الأذى عن من يدعو بهذا الدعاء للحماية."},{"id":90,"text":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَاّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ","title":"دعاء حسبي الله (أذكار الصباح والمساء)","source":"صحيح موقوف (شعيب الأرناؤوط). أبو داود: ٥٠٨١","reflection":"ابدأ يومك وانهه بمداومة أذكار الصباح والمساء القوية هذه، واثقاً في رعاية الله ورحمته، وجد السلام في قلبك بقول (حسبي الله) بإيمان وأمل.","lesson":"(حسبي الله) تجلب الهدوء وتزيل الخوف من القلب."},{"id":91,"text":"يَا حَيُّ يَا قَيُّوْمُ بِرَحْمَتِكَ أَسْتَغِيْثُ أَصْلِحْ لِي شَأْنِيْ كُلَّهُ وَلَا تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ","title":"دعاء يا حي يا قيوم الكامل (أذكار الصباح والمساء)","source":"حسن (الألباني). السلسلة الصحيحة: ٢٢٧","reflection":"هذه الأذكار الصباحية والمسائية تقرب من رحمة الله، وتساعد في إصلاح كل مشكلة، وتحفظ المسلم من الحزن والتوتر عن طريق التوسل بـ (يا حي يا قيوم) بثقة مطلقة.","lesson":"دعاء (يا حي يا قيوم) في الصباح والمساء يجلب عون الله في كل الأمور."},{"id":92,"text":"رَضِيْتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِيْنًا وَبِمُحَمَّدٍ نَبِيًّا","title":"دعاء الصباح والمساء لتقوية الإيمان","source":"صحيح لغيره (شعيب الأرناؤوط). تخريج المسند: ٢٣١١٢","reflection":"هذا الدعاء للصباح والمساء يملأ القلب بالإيمان، ويجلب السلام، ويساعد المسلم على الرضا بالله والإسلام والنبي، مما يجعل كل يوم أفضل بإيمان قوي.","lesson":"قول هذا الدعاء في الصباح والمساء يُبقي الإيمان قوياً في القلب."},{"id":93,"text":"اَللَّهُمَّ إِنِّي قَدْ تَصَدَّقْتُ بِعِرْضِي عَلَى عِبَادِكَ","title":"دعاء الصباح والمساء للمغفرة","source":"صحيح مقطوع (الألباني). أبو داود: ٤٨٨٦","reflection":"هذا الدعاء للمغفرة في الصباح والمساء يساعد المسلم على التخلي عن الغضب، ويجلب رحمة الله، ويملأ القلب بالسلام من خلال جعل العرض صدقة للآخرين.","lesson":"دعاء (اللهم إني) للمغفرة يمحو الذنوب ويجلب المغفرة."},{"id":95,"text":"اَللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ (لَكَ) بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","title":"أفضل دعاء للمغفرة (سيد الاستغفار)","source":"البخاري: ٦٣٠٦","reflection":"هذا الدعاء القوي، المعروف بسيد الاستغفار، يجلب الأمل والرحمة لكل مسلم يطلب مغفرة الله بقلب صادق ويريد أن يبقي إيمانه قوياً كل يوم.","lesson":"تشمل رحمة الله من يقول سيد الاستغفار بقلب صادق."},{"id":96,"text":"اللَّـهُ لَا إِلَـٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ ﴿٢٥٥﴾","title":"آية الكرسي (دعاء مسنون)","source":"البخاري: ٢٣١١","reflection":"تجلب آية الكرسي الأمان والطمأنينة القوية من الله، مما يجعل كل مسلم يشعر بالأمان والقرب منه عندما يتلو هذه الآية بإيمان وأمل في قلبه.","lesson":"حفظ الله يسع من يداوم على قراءة آية الكرسي بعد كل صلاة."},{"id":99,"text":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ ﴿١٠﴾","title":"دعاء للحماية من الكراهية","source":"سورة الحشر ٥٩:١٠","reflection":"دعاء المغفرة من سورة الحشر يساعد في إبقاء القلب نظيفاً ويجلب لطف الله، مما يجعل كل مسلم يشعر بالسلام والمحبة للآخرين في الحياة اليومية.","lesson":"رحمة الله تشمل من يدعو بدعاء المغفرة هذا بإيمان."},{"id":100,"text":"اَللَّهُمَّ عَافِنِي فِي بَدَنِي اَللَّهُمَّ عَافِنِيْ فِي سَمْعِي اَللَّهُمَّ عَافِنِيْ فِي بَصَرِي لَا إِلَهَ إِلَّا أَنْتَ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ لَا إِلَهَ إِلَّا أَنْتَ","title":"دعاء في الصباح والمساء (دعاء للصحة)","source":"حسن (الألباني). أبو داود: ٥٠٩٠","reflection":"ابدأ يومك وانهه بدعاء الصحة هذا، طالباً من الله جسداً قوياً، وسمعاً جيداً، وبصراً ثاقباً، والسلامة من الأذى والفقر والكفر وعذاب القبر.","lesson":"دعاء (اللهم عافني في بدني) يحفظ جسد المسلم آمناً من المرض والألم."},{"id":101,"text":"اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوْءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ","title":"دعاء الصباح للحماية من الشر","source":"صحيح (الألباني). الترمذي: ٣٥٢٩","reflection":"ابدأ صباحك بهذا الدعاء للحماية، واسأل الله أن يحفظك من أخطائك، وأذى الشيطان، وأي شر يمكن أن يمسك أو يمس المسلمين الآخرين.","lesson":"(اللهم) تحمي المسلم من شر الشيطان وشركه في الحياة اليومية."},{"id":102,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِيْ وَدُنْيَايَ وَأَهْلِيْ، وَمَالِيْ، اَللَّهُمَّ اسْتُرْ عَوْرَاتِيْ، وَآمِنْ رَوْعَاتِيْ، اَللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِيْنِيْ وَعَنْ شِمَالِي وَمِنْ فَوْقِيْ وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ","title":"دعاء للمغفرة والعافية","source":"صحيح (الألباني). أبو داود: ٥٠٧٤","reflection":"اسأل الله المغفرة، والأمان، والحماية في كل جزء من حياتك بهذا الدعاء، لتحمي دينك وعائلتك وثروتك وجميع جوانبك من الأذى في الدنيا والآخرة.","lesson":"دعاء (اللهم إني أسألك) يجلب مغفرة الله ويستر جميع الأخطاء."},{"id":104,"text":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","title":"دعاء للحماية من الحشرات (أعوذ بكلمات الله التامات)","source":"مسلم: ٢٧٠٨، ٢٧٠٩","reflection":"قل دعاء الحماية من الحشرات هذا، لطلب حفظ الله لك من كل شيء خلقه، وأي أذى يمكنه أن يلحقك أو يضرك، باستعمال كلماته التامات التي ترزقك الأمان والطمأنينة.","lesson":"دعاء (أعوذ بكلمات الله التامات) يحافظ على المسلمين آمنين من الحشرات والضرر الخفي."},{"id":106,"text":"اَللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ","title":"دعاء صباحي قوي (اللهم إني أصبحت)","source":"","reflection":"ابدأ يومك بهذا الدعاء الصباحي القوي لإبقاء الإيمان قوياً، وطلب مساعدة الله، وجلب البركة والسلامة لك ولعائلتك في كل خطوة تخطوها من الصباح إلى المساء.","lesson":"(اللهم) في دعاء الصباح هذا يجدد الإيمان ويبقي القلب قريباً من الله."},{"id":107,"text":"اَللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ","title":"دعاء الصباح (اللهم ما أصبح)","source":"","reflection":"ابدأ يومك بدعاء الصباح هذا لشكر الله على كل نعمة، وإبقاء قلبك ممتلئاً بـ (الحمد لله)، وتذكر عطاياه مع كل نفس تأخذه من شروق الشمس.","lesson":"(اللهم) في دعاء الصباح هذا تساعد المسلمين على إظهار الشكر لكل نعمة."},{"id":108,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا","title":"دعاء الصباح للرزق والعلم","source":"صحيح (الألباني). ابن ماجه: ٩٢٥","reflection":"اسأل الله بهذا الدعاء للرزق والعلم أن يملأ يومك بالثروة الحلال، والعلم النافع، والعمل الصالح الذي يجلب البركة وييسر حياتك من جميع النواحي.","lesson":"(اللهم) في دعاء الصباح هذا تجلب الرزق الطيب وتجعل العمل قوياً."},{"id":109,"text":"اَللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ","title":"دعاء اللهم إني (أذكار المساء)","source":"حسن (ابن باز). أبو داود: ٥٠٦٩","reflection":"أنهِ يومك بهذا الدعاء للمساء للحفاظ على الإيمان آمناً، وتذكر وحدانية الله، واسأل رحمته وحمايته مع حلول الليل واستراحتك من عملك اليومي.","lesson":"(اللهم) في دعاء المساء هذا تبقي الإيمان قوياً والقلب قريباً من الله."},{"id":110,"text":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ وَسُبْحَانَ اللَّهِ الْعَظِيْمِ","title":"أفضل الذكر والدعاء (سبحان الله وبحمده)","source":"البخاري: ٦٦٨٢","reflection":"اجعل لسانك مشغولاً بـ (سبحان الله وبحمده) لتنال حب الله، وتحصل على مغفرة الذنوب، وتملأ يومك بالبركة والسلام من أفضل الأذكار والأدعية في الإسلام.","lesson":"معنى (سبحان الله وبحمده) تجلب ثناء الله وتبقي القلب نقياً."},{"id":111,"text":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِيْ وَاهْدِنِيْ وَعَافِنِيْ وَارْزُقْنِيْ","title":"دعاء قوي للمغفرة والرزق","source":"مسلم: ٢٦٩٧","reflection":"دعاء المغفرة والرزق هذا يجلب الأمل في الرحمة، والهداية، والصحة، والثروة الحلال، مما يجعله دعاء موثوقاً لكل مسلم يسعى لعون الله في الحياة اليومية.","lesson":"(اللهم) تغفر جميع الذنوب وتجلب البركة في الرزق لمن يسأل."},{"id":112,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","title":"دعاء دخول السوق (دعاء مسنون)","source":"حسن (الألباني). الترمذي: ٣٤٢٨","reflection":"هذا الدعاء لدخول السوق يجلب ذكر الله للأماكن المزدحمة، مما يلهم المسلمين إبقاء إيمانهم حياً، والسعي للبركة والسلامة في جميع الأعمال اليومية والصفقات.","lesson":"(لا إله إلا الله وحده لا شريك له) تجلب بركة هائلة في العمل."},{"id":116,"text":"اَللَّهُ لَآ إِلٰهَ إِلَّا هُوَ الْحَىُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى السَّمٰوٰتِ وَمَا فِى الْأَرْضِ ۗ مَنْ ذَا الَّذِى يَشْفَعُ عِنْدَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ الْعَلِىُّ الْعَظِيمُ","title":"دعاء قبل النوم (آية الكرسي)","source":"البخاري، فتح الباري ٤/٤٨٧، برقم ٢٣١١","reflection":"اجعل قلبك يرتاح قبل الذهاب إلى الفراش بقراءة آية الكرسي، وهي آية قوية من سورة البقرة تجلب رعاية الله، والأمان، والسلام إلى ليلة كل مسلم.","lesson":"حفظ الله يسع من يقرأ آية الكرسي قبل النوم."},{"id":118,"text":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ يَا أَيُّهَا الْكَافِرُونَ ﴿١﴾ لَا أَعْبُدُ مَا تَعْبُدُونَ ﴿٢﴾ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾ وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ ﴿٤﴾ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٥﴾ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ﴿٦﴾","title":"دعاء قبل النوم (سورة الكافرون)","source":"صحيح (الألباني). الترمذي: ٣٤٠٣","reflection":"اجعل قلبك يرتاح قبل الذهاب إلى الفراش بقراءة سورة الكافرون، وهي دعاء ليلي قوي يحفظ إيمانك ويجلب مساعدة الله والسلام لكل مسلم.","lesson":"سورة الكافرون تبقي إيمان المسلم نقياً من الشرك قبل النوم."},{"id":122,"text":"اَللَّهُمَّ بِاسْمِكَ أَمُوْتُ وَأَحْيَا","title":"دعاء النوم","source":"البخاري: ٦٣١٤","reflection":"اجعل قلبك يرتاح بقول هذا الدعاء للنوم، متوكلاً على الله ليحفظك ويوقظك ببركته ورحمته في كل ليلة وصباح.","lesson":"(اللهم باسمك أموت وأحيا) تجلب السلام للقلب قبل الذهاب إلى الفراش."},{"id":123,"text":"بِاسْمِكَ اَللَّهُمَّ أَمُوْتُ وَأَحْيَا","title":"دعاء ما قبل النوم","source":"البخاري، فتح الباري ١١/١١٣ برقم ٦٣٢٤، مسلم ٤/٢٠٨٣ برقم ٢٧١١","reflection":"دع عقلك وجسدك يرتاحان بقول هذا الدعاء للنوم، متوكلاً على الله ليمنحك ليلة هادئة ويوقظك برحمته وبركته كل صباح.","lesson":"(باسمك اللهم أموت وأحيا) تبقي المسلم آمناً من الأذى خلال الليل."},{"id":124,"text":"اَلْحَمْدُ لِلَّهِ الَّذِى كَفَانِى وَآوَانِى وَأَطْعَمَنِى وَسَقَانِى وَالَّذِى مَنَّ عَلَىَّ فَأَفْضَلَ وَالَّذِى أَعْطَانِى فَأَجْزَلَ اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، اَللَّهُمَّ رَبَّ كُلِّ شَىْءٍ وَمَلِيْكَهُ وَإِلَهَ كُلِّ شَىْءٍ أَعُوْذُ بِكَ مِنَ النَّارِ","title":"دعاء الذهاب إلى النوم","source":"صحيح (الألباني). أبو داود: ٥٠٥٨","reflection":"أظهر الشكر لله بدعاء الذهاب إلى النوم هذا، متذكراً نعمه وطالباً حمايته ورحمته قبل أن ترتاح في الليل.","lesson":"(الحمد لله على كل حال) تملأ القلب بالشكر على كل نعمة من الله."},{"id":125,"text":"اَللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ","title":"دعاء الذهاب إلى النوم","source":"مسلم: ٢٧١٢","reflection":"توكل على الله في شأن روحك من خلال هذا الدعاء للذهاب إلى النوم، طالباً حمايته، ومغفرته، والعافية قبل أن ترتاح ليلاً.","lesson":"(اللهم إني أسألك) في هذا الدعاء للذهاب إلى النوم تجلب الأمان للروح."},{"id":126,"text":"اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اِقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","title":"دعاء يقرأ قبل النوم","source":"مسلم: ٢٧١٣","reflection":"اشعر بالقرب من الله بقول هذا الدعاء قبل النوم، متوكلاً عليه ليزيل همومك وديونك، ويمنحك البركة والسلام قبل أن ترتاح في الليل.","lesson":"(اللهم) في هذا الدعاء قبل النوم تذكر المسلم بعظمة الله."},{"id":127,"text":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوْذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","title":"دعاء يقال قبل النوم","source":"مسلم: ٢٧١٣، صحيح (الألباني). الترمذي: ٣٤٨١","reflection":"اجعل قلبك يرتاح بقول هذا الدعاء قبل النوم، طالباً من الله السلامة، وقضاء الدين، والسلام في ليلتك، متوكلاً على قدرته ورحمته قبل الذهاب إلى الفراش.","lesson":"(اللهم) في هذا الدعاء قبل النوم تجلب البركة والطمأنينة للقلب."},{"id":128,"text":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ (التَّامَّاتِ) مِنْ غَضَبِهِ وَعِقَابِهِ وَ(مِنْ) شَرِّ عِبَادِهِ وَمِنْ هَمَزَاتِ الشَّيَاطِيْنِ وَأَنْ يَحْضُرُوْنِ","title":"دعاء النوم","source":"حسن (الألباني). الترمذي: ٣٥٢٨","reflection":"يساعد دعاء النوم هذا المسلم على إيجاد السلام والأمان في الليل، طالباً حماية الله من الأذى، والشياطين، وغضبه قبل الذهاب إلى الفراش بقلب مطمئن.","lesson":"(أعوذ بالله) في هذا الدعاء للحماية تبعد غضب الله وعذابه."},{"id":129,"text":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ","title":"دعاء النوم","source":"البخاري ١١/١٢٦ برقم ٦٣٢٠، مسلم ٤/٢٠٨٤ برقم ٢٧١٤","reflection":"يسمح دعاء النوم هذا للمسلم بالتوكل على الله في شأن روحه قبل الذهاب إلى الفراش، طالباً رحمته ورعايته، تماماً كما يهبها لعباده الصالحين كل ليلة.","lesson":"(باسمك ربي) في هذا الدعاء للنوم تجلب السلام والأمان للقلب."},{"id":130,"text":"اَللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ","title":"دعاء قبل النوم","source":"صحيح (الألباني). الترمذي: ٣٣٩٨","reflection":"يساعد هذا الدعاء قبل النوم المسلم على طلب السلامة من الله من عذابه يوم القيامة، مما يجلب السلام والأمل قبل النوم كل ليلة.","lesson":"(اللهم) في هذا الدعاء قبل النوم تطلب من الله النجاة من العذاب في الآخرة."},{"id":131,"text":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِيْ فَاغْفِرْ لِي ذَنْبِيْ","title":"دعاء النوم","source":"حسن (شعيب الأرناؤوط). مسند أحمد: ٦٦٢٠","reflection":"يتيح دعاء النوم للمسلم طلب المغفرة والسلام من الله قبل الذهاب إلى الفراش، متوكلاً على رحمته ولطفه كل ليلة بقلب بسيط.","lesson":"(باسمك ربي) في هذا الدعاء للنوم تقرّب رحمة الله من القلب."},{"id":132,"text":"اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ","title":"دعاء النوم","source":"مسلم ٤/٢٠٨٥ برقم ٢٧١٥","reflection":"يذكرنا دعاء النوم هذا بشكر الله على الطعام، والماء، والمأوى، ورعايته، مما يملأ قلوبنا بـ (الحمد لله) قبل النوم ويعلمنا الثقة في رحمة الله كل ليلة.","lesson":"(الحمد لله الذي أطعمنا وسقانا، وكفانا، وآوانا، فكم ممن لا كافي له ولا مؤوي)."},{"id":133,"text":"اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيْكَهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ وَمِنْ شَرِّ الشَّيْطَانِ وَ شِرْكِهِ وَأَنْ أَقْتَرِفَ عَلَى نَفْسِيْ سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ","title":"أدعية قبل النوم","source":"صحيح (الألباني). الترمذي: ٣٣٩٢","reflection":"تساعد هذه الأدعية قبل النوم على حماية إيمانك وقلبك من الأذى، وتذكرك بالتوكل على الله، وطلب عونه، والابتعاد عن مكايد الشيطان كل ليلة قبل أن ترتاح.","lesson":"(اللهم عالم الغيب والشهادة فاطر السماوات والأرض رب كل شيء ومليكه)."},{"id":134,"text":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ مِنْ شَرِّ مَا خَلَقَ، وبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ","title":"أدعية قبل النوم","source":"صحيح (الأرناؤوط). أحمد: ١٥٤٩٩","reflection":"هذه الأدعية قبل النوم تساعدك على سؤال الله الرحمن الرحيم السلامة من الأذى، والفتن، وكل شر، مما يملأ قلبك بالسلام والتوكل على الرحمن كل ليلة قبل أن ترتاح.","lesson":"أعوذ بكلمات الله التامات التي لا يجاوزهن بر ولا فاجر."},{"id":135,"text":"بِسْمِ اللَّهِ وَضَعْتُ جَنْبِى اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ وَأَخْسِئْ شَيْطَانِيْ وَفُكَّ رِهَانِيْ وَاجْعَلْنِيْ فِي النَّدِىِّ الْأَعْلَى","title":"أدعية قبل النوم","source":"صحيح (الألباني). سنن أبي داود: ٥٠٥٤","reflection":"تساعدك هذه الأدعية قبل النوم على سؤال الله المغفرة، والبركة، والأمان من الشيطان، مما يجعل قلبك هادئاً وإيمانك قوياً قبل النوم كل ليلة.","lesson":"(بسم الله) و (اللهم) تجلبان السلام والمغفرة قبل النوم."},{"id":136,"text":"اَللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِيْ إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ","title":"دعاء قبل النوم","source":"البخاري، فتح الباري ١١/١١٣ برقم ٦٣١٣، مسلم ٤/٢٠٨١ برقم ٢٧١٠","reflection":"دعاء قبل النوم هذا هو درع قوي لقلبك وعقلك، يساعدك على التوكل على الله، وإيجاد السلام، وطلب الحماية أثناء راحتك، اتباعاً للسنة وبناءً للإيمان كل ليلة.","lesson":"(اللهم أسلمت نفسي إليك) تعلم التوكل الكامل على الله قبل النوم."},{"id":138,"text":"لَا إِلَهَ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ","title":"دعاء من تعار من الليل","source":"صحيح من قبل الحاكم. الإمام الذهبي ١/٥٤٠؛ النسائي، عمل اليوم والليلة رقم ٢٠٢، ابن السني رقم ٧٥٧. انظر أيضاً، صحيح الجامع ٤:٢١٣","reflection":"هذا الدعاء عند التقلب أثناء الليل يساعدك على تذكر عظمة الله، ويجلب البركة لنومك، ويبقي قلبك قريباً من الإيمان حتى في أهدأ الساعات.","lesson":"(لا إله إلا الله الواحد القهار، رب السماوات والأرض وما بينهما العزيز الغفار)."},{"id":139,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيْمِ، رَبِّ اغْفِرْ لِي","title":"دعاء الاستيقاظ","source":"صحيح (الألباني). أبو داود: ٥٠٦٠","reflection":"هذا الدعاء للاستيقاظ يملأ صباحك بالبركة، ويقربك من الله، ويساعدك على بدء يومك بالإيمان، والمغفرة، وذكر الله على لسانك.","lesson":"قراءة هذا الدعاء تجلب البركة والمغفرة في بداية اليوم."},{"id":141,"text":"اَلْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُوْرُ","title":"دعاء الاستيقاظ","source":"البخاري، انظر العسقلاني، فتح الباري ١١/١١٣ برقم ٦٣١٤؛ مسلم ٤/٢٠٨٣ برقم ٢٧١١","reflection":"يملأ دعاء الاستيقاظ هذا قلبك بـ (الحمد لله)، ويجلب البركة لصباحك، ويذكرك برحمة الله عندما تبدأ يوماً جديداً بالإيمان والأمل في يوم قادم جيد.","lesson":"قراءة هذا الدعاء تجلب البركة والامتنان في بداية اليوم."},{"id":142,"text":"اَلْحَمْدُ لِلَّهِ الَّذِي عَافَانِيْ فِي جَسَدِيْ، وَرَدَّ عَلَيَّ رُوحِيْ، وَأَذِنَ لِي بِذِكْرِهِ","title":"دعاء الاستيقاظ لصلاة الفجر","source":"الترمذي ٥/٤٧٣. انظر صحيح الترمذي للألباني ٣/١٤٤","reflection":"دعاء الاستيقاظ لصلاة الفجر هذا يملأ قلبك بالشكر لله على إعطائك الحياة، والصحة، والفرصة لذكره في وقت الفجر، مما يجلب البركة والقوة ليومك منذ بدايته.","lesson":"قراءة هذا الدعاء تجلب البركة والصحة في بداية الفجر."},{"id":144,"text":"أَعُوْذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","title":"دعاء الرؤيا السيئة (الحلم المفزع)","source":"[١] البخاري: ٧٠٤٤\n[٢] مسلم: ٦٠٤١\n[٣] صحيح (الألباني). الترمذي: ٢٢٨٠","reflection":"دعاء الرؤيا السيئة يساعدك على طلب الحماية من الله ضد الشيطان، ويجلب الهدوء والأمان لقلبك بعد كابوس، ويُذكّرك بالتوكل على رحمة الله في كل أوقات الخوف.","lesson":"قراءة هذا الدعاء بعد حلم سيئ يجلب الحماية من الله ضد الشيطان."},{"id":146,"text":"اَلْحَمْدُ لِلَّهِ الَّذِي كَسَانِيْ هَذَا الثَّوْبَ وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِنِّيْ وَلَا قُوَّةٍ","title":"دعاء لبس الثوب","source":"حسن (الألباني). أبو داود: ٤٠٢٣","reflection":"يُذكّرك دعاء لبس الثوب بشكر الله على كل رداء، وإظهار الشكر لرزقه وتذكر أن جميع النعم تأتي منه وحده، وليس بقوتنا أو حولنا.","lesson":"قراءة هذا الدعاء تجلب البركة في كل لباس ترتديه."},{"id":147,"text":"اَللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيْهِ أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ وَأَعُوْذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ","title":"دعاء لبس الثوب الجديد","source":"صحيح (الألباني). الترمذي: ١٧٦٧","reflection":"يساعدك دعاء ارتداء الملابس الجديدة على شكر الله على نعمه، طالباً الخير من لباسك الجديد وساعياً للسلامة من أي ضرر، مما يملأ قلبك بالشكر والبركة في كل مرة ترتدي فيها شيئاً جديداً.","lesson":"قراءة هذا الدعاء تجلب البركة والحماية في الملابس الجديدة."},{"id":148,"text":"تُبْلَی وَيُخْلِفُ اللَّهُ تَعَالَی","title":"دعاء لمن لبس ثوباً جديداً","source":"صحيح (الألباني). أبو داود: ٤٠٢٠","reflection":"الدعاء لمن يرتدي ملابس جديدة هو وسيلة لجلب البركة للآخرين، من خلال سؤال الله أن يبارك لهم في لباسهم الجديد وأن يمنحهم المزيد، مما يملأ القلوب بالحب والشكر على كل عطاء من الله.","lesson":"قراءة هذا الدعاء تجلب البركة والسعادة للآخرين."},{"id":150,"text":"أَبْلِيْ وَأَخْلِقِيْ","title":"دعاء لمن لبست ثوباً جديداً (للأنثى)","source":"البخاري: ٥٩٩٣","reflection":"الدعاء لمن ترتدي ملابس جديدة هو وسيلة لسؤال الله طول العمر، والبركة، والسعادة للأخت أو الأم، متمنياً لها أن تستمتع بلباسها حتى يبلى بالإيمان والعمل الصالح.","lesson":"قراءة هذا الدعاء تجلب البركة والسعادة للأخوات والأمهات."},{"id":151,"text":"أَبْلَ وَأَخْلَقْ","title":"دعاء لمن لبس ثوباً جديداً (للذكر)","source":"البخاري: ٥٩٩٣","reflection":"الدعاء لمن يلبس ملابس جديدة هو طريقة بسيطة لسؤال الله عمراً طويلاً وبركة لأخيك أو أبيك أو ابنك، متمنياً له أن يستمتع بثوبه الجديد حتى يبلى بالإيمان والسعادة.","lesson":"قراءة هذا الدعاء تجلب البركة والسعادة للإخوة والآباء والأبناء."},{"id":152,"text":"اِلْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا","title":"دعاء لمن لبس ثوباً جديداً","source":"صحيح (الألباني). ابن ماجه: ٣٥٥٨","reflection":"دعاء لبس الثوب الجديد يسأل الله حياة طيبة، وبركة، وشرف الموت كشهيد، متمنياً للشخص أن يستمتع بلباسه الجديد مع الإيمان والعمل الصالح في كل مرة يرتدي فيها شيئاً جديداً.","lesson":"قراءة هذا الدعاء تجلب البركة والتمنيات الطيبة للشخص الذي يرتدي ملابس جديدة."},{"id":153,"text":"اِلْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا وَيَرْزُقُكَ اللَّهُ قٌرَّةَ عَيْنٍ فِي الدُّنْيَا وَالْاَخِرَةِ","title":"دعاء لمن لبس ثوباً جديداً","source":"صحيح (الألباني). صحيح الجامع: ١٢٣٤","reflection":"دعاء لبس الثوب الجديد يسأل الله حياة طيبة، والبركة، وقرة عين في الدنيا والآخرة، متمنياً للشخص أن يستمتع بلباسه الجديد مع الإيمان والسعادة في كل مرة يرتدي فيها.","lesson":"قراءة هذا الدعاء تجلب البركة والسعادة لمن يرتدي ملابس جديدة."},{"id":154,"text":"بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","title":"دعاء الخروج من المنزل","source":"صحيح (الألباني). أبو داود: ٥٠٩٥","reflection":"يُذكِّر دعاء الخروج من المنزل كل مسلم بالتوكل على الله، وطلب عونه، وسؤال البركة والسلامة قبل الخروج، مما يجعل كل رحلة تبدأ بالإيمان والأمل في رعاية الله.","lesson":"قراءة هذا الدعاء تجلب البركة والحماية قبل الخروج من المنزل."},{"id":155,"text":"بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ اَللَّـهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نَزِلَّ أَوْ نَضِلَّ أَوْ نَظْلِمَ أَوْ نُظْلَمَ أَوْ نَجْهَلَ أَوْ يُجْهَلَ عَلَيْنَا","title":"دعاء قبل الخروج من المنزل","source":"صحيح (الألباني). الترمذي: ٣٤٢٧","reflection":"يساعد دعاء قبل الخروج من المنزل المسلمين على بدء يومهم بالإيمان، وسؤال الله البركة، والحماية من الأذى، والوقاية من الأخطاء أو التعرض للظلم أثناء التواجد بالخارج.","lesson":"دعاء الخروج من المنزل يجلب عون الله ويشملك بحمايته."},{"id":156,"text":"اَللَّـهُمَّ إِنِّي أَعُوْذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضَلَّ، أَوْ أَزِلَّ، أَوْ أُزَلَّ، أَوْ أَظْلِمَ، أَوْ أُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ","title":"دعاء النظر إلى السماء عند الخروج","source":"صحيح (الألباني). أبو داود: ٥٠٩٤","reflection":"هذا الدعاء عند الخروج من المنزل هو درع قوي للمسلمين، يطلب من الله فيه البركة، والسلامة من الأخطاء، والحماية من الأذى أو التعرض للظلم وأنت تخطو للخارج بإيمان.","lesson":"دعاء الخروج يحميك من أن تضل أو تُضَل."},{"id":157,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","title":"دعاء الدخول إلى المنزل","source":"حسن (ابن باز). أبو داود: ٥٠٩٦","reflection":"دعاء دخول المنزل يجلب البركة والسلام، حيث تسأل الله الخير والسلامة والتوكل عليه في كل مرة تدخل فيها، مما يجعل منزلك مكاناً للإيمان والراحة.","lesson":"دعاء دخول المنزل يجلب بركة الله والسلامة إلى بيتك."},{"id":158,"text":"اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ","title":"دعاء قبل الدخول إلى المنزل","source":"حسن (ابن حجر). مشكاة المصابيح: ٤/٣١٦","reflection":"اجلب السلام والبركة إلى منزلك بقول هذا الدعاء قبل الدخول، للسماح لرحمة الله وبركاته بملء عائلتك وحماية الجميع في الداخل من الأذى والمشاكل.","lesson":"قول (السلام عليكم ورحمة الله وبركاته) يجلب بركة الله للمنزل."},{"id":159,"text":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","title":"دعاء عند دخول المنزل","source":"[١] حسن (ابن باز). أبو داود: ٥٠٩٦\n[٢] مسلم: ٢٠١٨","reflection":"دع منزلك يمتلئ برعاية الله والتوكل عليه بقول هذا الدعاء عند دخول المنزل، جاعلاً كل خطوة في الداخل والخارج آمنة باسمه ومبقياً عائلتك قريبة من رحمته.","lesson":"البسملة في هذا الدعاء لدخول المنزل تُبعد الشيطان عن بيتك."},{"id":160,"text":"بِسْمِ اللَّهِ، اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","title":"دعاء قبل دخول الخلاء (الحمام)","source":"البخاري: ١٤٢","reflection":"حافظ على سلامتك من الأذى والنجاسة بقول هذا الدعاء قبل دخول الخلاء، دَعْ اسْمَ الله يحميك من كل شر ويبقي قلبك نقياً وممتلئاً بالإيمان.","lesson":"البسملة في هذا الدعاء قبل دخول الخلاء تبعد الشياطين عنك."},{"id":163,"text":"أَشْهَدُ أَنْ لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ رَضِيتُ بِاللَّهِ رَبًّا وَبِمُحَمَّدٍ رَسُولًا وَبِالْإِسْلَامِ دِينًا","title":"الدعاء بعد سماع الأذان","source":"مسلم: ٣٨٦","reflection":"اجعل إيمانك ينمو قوياً بقول دعاء الأذان بعد سماع النداء للصلاة، مظهراً الحب لله ورسوله وللإسلام، وجالباً البركة لصلاتك وعملك اليومي.","lesson":"قول (أشهد أن لا إله إلا الله) في دعاء الأذان يجعل الإيمان يشرق في القلب."},{"id":164,"text":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اَللَّهُمَّ بَارِكَ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ","title":"الدعاء بعد الأذان (الصلاة الإبراهيمية)","source":"مسلم: ٣٨٤","reflection":"هذا الدعاء بعد الأذان يجلب البركات والرحمة من الله، رافعاً قدر النبي محمد صلى الله عليه وسلم وآله، ويجلب البركة لأولئك الذين يقرؤون الصلاة الإبراهيمية بعد سماع النداء للصلاة.","lesson":"يمنح الله البركة لمن يصلي على النبي الصلاة الإبراهيمية بعد الأذان."},{"id":165,"text":"اَللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا وَالْوَسِيْلَةَ وَالْفَضِيْلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُوْدًا الَّذِيْ وَعَدْتَهُ","title":"الدعاء بعد الأذان","source":"البخاري: ٦١٤","reflection":"هذا الدعاء بعد الأذان يجلب أجوراً خاصة، ويساعد في رفع درجة النبي محمد صلى الله عليه وسلم، ويجلب البركة والقبول لمن يذكر الله بعد سماع الأذان.","lesson":"يمنح الله وعد المقام المحمود للنبي محمد صلى الله عليه وسلم."},{"id":168,"text":"اَللَّهُمَّ أَرْشِدِ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِيْنَ","title":"الدعاء للأئمة والمؤذنين (دعاء الاستغفار)","source":"صحيح (الألباني). أبو داود: ٥١٧","reflection":"هذا الدعاء للأئمة والمؤذنين يجلب هداية الله للقادة والمغفرة لمن ينادون للصلاة، مما يجعل المسجد مكاناً للبركة والوحدة لجميع المسلمين.","lesson":"قول (اللهم) يعطي الهداية للأئمة ليقودوا الصلاة بإيمان صادق."},{"id":170,"text":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","title":"الدعاء بعد الوضوء","source":"مسلم: ٢٣٤، ٥٧٦","reflection":"هذا الدعاء بعد الوضوء يقوي إيمان المسلم، ويجلب البركة لكل صلاة، ويساعد على إبقاء القلب نقياً بتذكر الله وصدق رسالة محمد صلى الله عليه وسلم.","lesson":"قول (أشهد أن لا إله إلا الله) بعد الوضوء يجلب المزيد من الأجر على كل عمل."},{"id":171,"text":"اَللَّهُمَّ اجْعَلْنِيْ مِنَ التَّوَّابِيْنَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِيْنَ","title":"دعاء ما بعد الوضوء","source":"صحيح (الألباني). الترمذي: ٥٥","reflection":"دعاء ما بعد الوضوء يقرب المسلم من الله بطلب المغفرة والطهارة، مما يجعل كل وضوء فرصة لكسب البركة وإبقاء القلب نقياً للصلاة والعمل الصالح.","lesson":"قول (اللهم) في دعاء ما بعد الوضوء هذا يساعد المسلم في الحصول على البركة في كل صلاة."},{"id":172,"text":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوْبُ إِلَيْكَ","title":"الدعاء بعد الوضوء","source":"النسائي في عمل اليوم والليلة: ١٧٣. وانظر: الألباني في إرواء الغليل: ١/١٣٥، و٢/٩٤","reflection":"هذا الدعاء بعد الوضوء يساعد المسلم على تذكر عظمة الله وطلب الاستغفار، مما يجعل كل وضوء وقتاً لتنقية القلب والاستعداد للصلاة بالبركة والإيمان.","lesson":"قول (سبحانك اللهم وبحمدك) في هذا الدعاء بعد الوضوء يجلب البركة."},{"id":173,"text":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِيْ نُوْرًا وَّفِي لِسَانِىْ نُوْرًا وَّاجْعَلْ فِي سَمْعِىْ نُوْرًا وَّاجْعَلْ فِي بَصَرِىْ نُوْرًا وَّاجْعَلْ مِنْ خَلْفِي نُوْرًا وَّمِنْ أَمَامِيْ نُوْرًا وَّاجْعَلْ مِنْ فَوْقِىْ نُوْرًا وَّمِنْ تَحْتِىْ نُوْرًا اَللَّهُمَّ أَعْطِنِىْ نُوْرًا","title":"الدعاء عند الذهاب إلى المسجد (دعاء النور)","source":"البخاري: ٦٣١٦","reflection":"ينير هذا الدعاء عند الذهاب إلى المسجد قلب المسلم وحياته بنور الله، جاعلاً كل خطوة إلى المسجد طريقاً للحصول على البركة والنور والرحمات في العمل والإيمان.","lesson":"قول (اللهم) في دعاء النور يجلب النور للقلب ويجعل العمل يشرق."},{"id":174,"text":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا، وَعَظِّمْ لِي نُورًا، وَاجْعَلْ لِي نُورًا، وَاجْعَلْنِي نُورًا، اَللَّهُمَّ أَعْطِنِي نُورًا، وَاجْعَلْ فِي عَصَبِي نُورًا، وَفِي لَحْمِي نُورًا، وَفِي دَمِي نُورا، وَفِي شَعْرِي نُورًا، وَفِي بَشَرِي نُورًا","title":"دعاء الذهاب إلى المسجد","source":"البخاري: ٦٣١٦","reflection":"يملأ هذا الدعاء عند الذهاب إلى المسجد قلب المسلم وجسده وروحه بنور الله، مما يجعل كل خطوة إلى المسجد طريقاً للحصول على البركة والنور والرحمات في العمل والإيمان.","lesson":"قول (اللهم) في دعاء النور يجلب النور لكل جزء من الجسد والقلب."},{"id":175,"text":"بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ، اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","title":"دعاء دخول المسجد","source":"صحيح (الألباني). أبو داود: ٤٦٥، مسلم: ٧١٣","reflection":"هذا الدعاء عند دخول المسجد يدخل المسلم في رحمة الله وبركاته، جاعلاً كل خطوة داخل المسجد طريقاً لنيل البركة، والسلام، والقرب من رسول الله صلى الله عليه وسلم.","lesson":"البسملة في دعاء دخول المسجد تجلب البركة والسلامة في كل خطوة."},{"id":176,"text":"بِسْمِ اللَّهِ اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","title":"دعاء الدخول إلى المسجد","source":"حسن (الألباني). ابن السني: ٨٨، مسلم: ٧١٣","reflection":"إن الدخول إلى المسجد بهذا الدعاء يقرّب رحمة الله، ويساعد في الحفاظ على نقاء قلبك، ويذكرك بتكريم النبي محمد صلى الله عليه وسلم كلما دخلت.","lesson":"قول (اللهم صل على محمد) في دعاء الدخول للمسجد يجلب البركة."},{"id":177,"text":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","title":"الدعاء لدخول المسجد (رب اغفر لي ذنوبي)","source":"صحيح (الألباني). ابن ماجه: ٧٧١","reflection":"يسأل دعاء دخول المسجد هذا الله عز وجل المغفرة والرحمة، مما يهيئ قلبك للصلاة ويساعدك على بدء وقتك في المسجد بروح نقية وأمل في البركة.","lesson":"قول (رب اغفر لي) في الدعاء قبل دخول المسجد يقرّب مغفرة الله."},{"id":178,"text":"أَعُوْذُ بِاللَّهِ الْعَظِيمِ وَبِوَجْهِهِ الْكَرِيمِ وَسُلْطَانِهِ الْقَدِيْمِ مِنَ الشَّيْطَانِ الرَّجِيْمِ، بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","title":"الدعاء قبل دخول المسجد (أعوذ بالله)","source":"صحيح (الألباني). أبو داود: ٤٦٥، ٤٦٦","reflection":"هذا الدعاء قبل دخول المسجد يبعد الشيطان، ويجلب رحمة الله، ويساعدك على بدء وقتك في المسجد بقلب نقي وحب للنبي صلى الله عليه وسلم.","lesson":"الاستعاذة (أعوذ بالله) في دعاء دخول المسجد تعطي حماية قوية من وساوس الشيطان."},{"id":179,"text":"بِسْمِ اللَّهِ اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ فَضْلِكَ","title":"دعاء الخروج من المسجد (اللهم إني أسألك)","source":"حسن (الألباني). ابن السني: ٨٨، مسلم: ٧١٣","reflection":"دعاء الخروج من المسجد هذا يسأل الله من فضله، ويُبقي النبي صلى الله عليه وسلم في قلبك، ويساعدك على الخروج بالبركة والأمل في المزيد من الأعمال الصالحة في حياتك اليومية.","lesson":"قول (اللهم إني أسألك) في دعاء الخروج من المسجد يجلب فضل الله في العمل اليومي."},{"id":180,"text":"بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اَللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ","title":"دعاء عند الخروج من المسجد","source":"صحيح (الألباني). ابن ماجه: ٧٧٣","reflection":"دعاء الخروج من المسجد هذا يسأل الله من فضله، ويُبقي الشيطان بعيداً، ويساعدك على الخروج بسلام، ذاكراً النبي صلى الله عليه وسلم وحاملاً البركة في عملك اليومي.","lesson":"البسملة في دعاء الخروج من المسجد تحفظ الإيمان وتجعل العمل قوياً في الخارج."},{"id":181,"text":"اَللَّهُمَّ أَجِرْنِيْ مِنَ الشَّيْطَانِ الرَّجِيْمِ","title":"دعاء الخروج من المسجد (اللهم أجرني)","source":"صحيح (ابن حبان). ابن حبان: ٢٠٤٧","reflection":"وأنت تخرج من المسجد، يحفظك هذا الدعاء من مكايد الشيطان ويجلب عون الله، مما يجعل طريقك للبيت وحياتك اليومية مليئة ببركته ورعايته.","lesson":"قول (اللهم أجرني من النار) يحفظ المسلم من وساوس الشيطان."},{"id":182,"text":"اَللَّهُمَّ اعْصِمْنِى مِنَ الشَّيْطَانِ الرَّجِيْمِ","title":"دعاء الخروج من المسجد","source":"صحيح (الألباني). ابن ماجه: ٧٧٣","reflection":"عندما يغادر المسلم المسجد، يطلب هذا الدعاء من الله أن يبعد الشيطان ويجلب السلام، مما يجعل كل خطوة في الخارج مليئة برعايته وسلامته لليوم الذي أمامه.","lesson":"قول (اللهم) يحفظ القلب من شر الشيطان بعد الخروج من المسجد."},{"id":183,"text":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ","title":"دعاء الخروج من المسجد (اللهم اغفر لي)","source":"صحيح (الألباني). ابن ماجه: ٧٧١","reflection":"وأنت تخرج من المسجد، يطلب هذا الدعاء من الله المغفرة وعطاياه، مما يجعل يومك أكثر إشراقاً بالبركة والرحمة وتُفتح لك أبواب الخير.","lesson":"قول (اللهم اغفر لي) يساعد المسلم في نيل المغفرة للذنوب بعد الصلاة."},{"id":184,"text":"لَا رَدَّهَا اللَّهُ عَلَيْكَ","title":"الدعاء على من ينشد ضالة في المسجد","source":"صحيح (الألباني). الترمذي: ١٣٢١","reflection":"يعلم دعاء المسجد هذا احترام بيت الله ويحافظ على هدوء المسجد، ويُذكِّر المسلمين باتباع الطريقة الصحيحة عندما يُفقد أو يضيع شيء داخل المسجد.","lesson":"دعاء المسجد يساعد في الحفاظ على المسجد آمناً من النداءات العالية حول المفقودات."},{"id":185,"text":"لَا أَرْبَحَ اللَّهُ تِجَارَتَكَ","title":"الدعاء على من يبيع ويبتاع في المسجد","source":"صحيح (الألباني). الترمذي: ١٣٢١","reflection":"يُذكّر دعاء المسجد هذا المسلمين بإبقاء المسجد خالصاً للصلاة وذكر الله، ويعلّم الطريقة الصحيحة لاحترام بيت الله وإبقاء التجارة خارج أبوابه.","lesson":"دعاء المسجد يساعد المسلمين على تذكر عدم خلط التجارة مع الصلاة والعمل."},{"id":187,"text":"اَللَّهُمَّ بَاعِدْ بَيْنِيْ وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اَللَّهُمَّ نَقِّنِيْ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اَللَّهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ","title":"الدعاء بعد تكبيرة الإحرام","source":"البخاري: ٧٤٤","reflection":"دعاء ما بعد التكبير في الصلاة يساعد المسلم على بدء الصلاة بقلب نقي، سائلاً الله أن يباعد عنه الخطايا ويجعل كل صلاة طاهرة ومليئة بالبركة والمغفرة.","lesson":"قول (اللهم باعد) في دعاء الاستفتاح يُبعد الذنوب كبُعد المشرق والمغرب في الصلاة."},{"id":188,"text":"اَللَّهُمَّ رَبَّ جِبْرَائِيْلَ وَمِيْكَائِيْلَ وَإِسْرَافِيلَ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ اِهْدِنِيْ لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِيْ مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيْمٍ","title":"دعاء بدء صلاة التهجد","source":"مسلم: ٧٧٠","reflection":"دعاء صلاة التهجد هذا قبل الصلاة يقرب المسلم من الله، ويملأ القلب بالبركة والإيمان، ويساعد على الهداية إلى الصراط المستقيم في سكون الليل.","lesson":"يهب الله البركة لمن يدعو بهذا الدعاء في صلاة التهجد."},{"id":190,"text":"اَللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ.","title":"دعاء الاستفتاح في التهجد","source":"مسلم: ٧٧١","reflection":"يساعد هذا الدعاء في التهجد المسلم على سؤال الله المغفرة وحسن الخلق، مما يجعل صلاة الليل أكثر بركة ومليئة بالأمل لمن يسعى لرحمة الله وهدايته.","lesson":"قول (اللهم) في هذا الدعاء في التهجد يجلب التوبة الصادقة للإسلام في القلب."},{"id":191,"text":"لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ بِيَـدَيْكَ، وَالشَّـرُّ لَيْسَ إِلَيْـكَ، أَنَا بِكَ وَإِلَيْكَ، تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","title":"دعاء الاستفتاح للصلاة (بعد تكبيرة الإحرام)","source":"مسلم: ٧٧١","reflection":"دعاء ما قبل الصلاة هذا بعد التكبير يُذكّر المسلم بأن يبدأ الصلاة بقلب نقي، طالباً مغفرة الله والبركة قبل كل صلاة لعمل وإيمان أفضل.","lesson":"دعاء ما قبل الصلاة يساعد المسلمين على بدء الصلاة بالالاستغفار والنية الخالصة."},{"id":192,"text":"اَللَّهُ أَكْبَرُ كَبِيرًا، اَللَّهُ أَكْبَرُ كَبِيرًا، اَللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا","title":"دعاء الاستفتاح للصلاة (الله أكبر كبيراً)","source":"حسن لغيره (شعيب الأرناؤوط). أبو داود: ٧٦٤","reflection":"دعاء الاستفتاح مع (الله أكبر كبيراً) يملأ القلب بالثناء والشكر، مساعِداً المسلم على بدء الصلاة بإيمان قوي وبركة من التكبيرة الأولى إلى الأخيرة.","lesson":"قول (الله أكبر) في دعاء الاستفتاح يرفع القلب بالثناء والتوحيد الصادق."},{"id":195,"text":"سُبْحَانَ رَبِّيَ الْعَظِيمِ","title":"تسبيح الركوع (سبحان ربي العظيم)","source":"صحيح (الألباني). الترمذي: ٢٦٢","reflection":"دعاء الركوع هذا يقرب المسلم من الله، مظهراً الاحترام والثناء، ويساعد في إبقاء القلب خاشعاً خلال كل خطوة من الصلاة.","lesson":"قول (سبحان ربي العظيم) في الركوع يظهر الاحترام الحقيقي لعظمة الله."},{"id":196,"text":"سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ","title":"تسبيح الركوع (سبحان ربي العظيم وبحمده)","source":"سنده حسن (شعيب الأرناؤوط). أبو داود: ٨٧٠","reflection":"دعاء الركوع هذا يساعد المسلم على الثناء على الله بالكلمات والقلب معاً، مما يجعل كل ركوع في الصلاة أكثر معنى ومليئاً بالبركة لمن يتبع السنة.","lesson":"قول (سبحان ربي العظيم وبحمده) في الركوع يجلب أجراً وثناءً مضاعفاً."},{"id":197,"text":"سُبُّوْحٌ قُدُّوْسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوْحِ","title":"دعاء في الركوع (سبوح قدوس)","source":"صحيح (الألباني). أبو داود: ٨٧٢","reflection":"يساعد دعاء الركوع هذا المسلم على الثناء على الله كرب للملائكة والروح، مما يجعل كل ركوع في الصلاة أكثر تميزاً ومليئاً بالاحترام لعظمة الله.","lesson":"قول (سبوح قدوس) في الركوع يظهر الاحترام العميق لأسماء الله الطاهرة والمقدسة."},{"id":198,"text":"اَللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ خَشَعَ لَكَ سَمْعِيْ وَبَصَرِيْ وَمُخِّيْ وَعِظَامِيْ وَعَصَبِيْ","title":"دعاء في الركوع (اللهم لك ركعت وبك آمنت)","source":"صحيح (الألباني). أبو داود: ٧٦٠","reflection":"دعاء الركوع هذا يساعد المسلم على إظهار الثقة والتسليم الكامل لله، مما يجعل كل ركوع في الصلاة وقتًا للإيمان الحقيقي والاحترام للخالق بكل جوارح الجسد.","lesson":"قول (اللهم لك ركعت) في الركوع يظهر العمل الكامل والثقة في قوة الله."},{"id":199,"text":"سُبْحَانَ ذِي الْجَبَرُوْتِ وَالْمَلَكُوْتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ","title":"دعاء في الركوع","source":"صحيح (الألباني). أبو داود: ٨٧٣","reflection":"دعاء الركوع هذا يساعد المسلم على الثناء على قوة الله وعظمته، جاعلا كل ركوع في الصلاة وقتا لتذكر تحكم الله في كل شيء ومكانته العالية.","lesson":"قول (سبحان ذي الجبروت) في الركوع يظهر الثناء الحقيقي على قوة الله وحكمه."},{"id":200,"text":"سُبْحَانَكَ وَبِحَمْدِكَ أَسْتَغْفِرُكَ وَأَتُوْبُ اِلَيْكَ","title":"دعاء في الركوع (سبحانك وبحمدك أستغفرك)","source":"حسن (الألباني). السلسلة الصحيحة: ٣٠٣٢","reflection":"دعاء الركوع هذا يقرب المسلم من رحمة الله ومغفرته، مما يجعل كل ركوع في الصلاة وقتا للثناء والتوبة وطلب البركة من الغفور.","lesson":"يغفر الله الذنوب عندما يقرأ المسلم دعاء الركوع بقلب مليء بالإيمان."},{"id":201,"text":"سُبْحَانَكَ اَللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اَللَّهُمَّ اغْفِرْ لِي","title":"دعاء في الركوع (دعاء للمغفرة)","source":"[١] البخاري: ٧٩٤\n[٢] سورة النصر ١١٠:٣","reflection":"يُقرب دعاء الركوع هذا المسلم من رحمة الله ومغفرته، مبقيا القلوب متواضعة وخالصة أثناء الانحناء في الصلاة وسائلا فضل الله وبركته في كل صلاة.","lesson":"تقترب رحمة الله عندما يقول المسلم (سبحانك اللهم) في الركوع."},{"id":202,"text":"سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ","title":"دعاء الرفع من الركوع (سمع الله لمن حمده)","source":"البخاري: ٧٩٦","reflection":"يُذكر دعاء الرفع من الركوع المسلمين بأن الله يستمع لكل كلمة ثناء، مما يجعل الصلاة ذات معنى أعمق ويملأ القلب بالشكر والرجاء في بركة الله وإحسانه.","lesson":"يستمع الله لمن يقول (سمع الله لمن حمده) بعد الركوع."},{"id":203,"text":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","title":"دعاء الرفع من الركوع (اللهم ربنا لك الحمد)","source":"مسلم: ٤٧٧","reflection":"يملأ دعاء الرفع من الركوع القلب بالثناء على الله، مذكرًا المسلمين بأن كل القوة والنعم تأتي منه وحده، ويجلب البركة والشكر في كل صلاة وعمل يومي.","lesson":"تصل نعم الله وبركته لمن يقول (ربنا لك الحمد) بعد الركوع."},{"id":204,"text":"(اَللَّهُمَّ) رَبَّنَا لَكَ الْحَمْدُ","title":"دعاء الرفع من الركوع (ربنا لك الحمد)","source":"البخاري: ٧٩٦","reflection":"دعاء الرفع من الركوع القصير هذا يملأ الصلاة بالشكر، مساعدًا المسلمين على تذكر نعم الله وجاعلا كل صلاة مليئة بالبركة والإيمان لمن يقوله بقلب صادق.","lesson":"يكبر الثناء على الله في القلب عندما يقول المسلم (ربنا لك الحمد) بعد الركوع."},{"id":205,"text":"(اَللَّهُمَّ) رَبَّنَا وَلَكَ الْحَمْدُ","title":"دعاء الرفع من الركوع (ربنا ولك الحمد)","source":"البخاري: ٧٩٥","reflection":"يساعد دعاء الرفع من الركوع المسلمين على إظهار الشكر لله في الصلاة، مما يجعل كل صلاة مليئة بالبركة ويذكر القلوب بالثناء على الله على جميع نعمه وإحسانه في الحياة اليومية.","lesson":"تأتي بركة الله لمن يقول (ربنا ولك الحمد) بعد الركوع."},{"id":207,"text":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ","title":"دعاء بعد الرفع من الركوع","source":"مسلم: ٤٧٦","reflection":"يملأ دعاء الرفع من الركوع قلبك بالثناء على الله، مما يجعل صلاتك أكمل ويجلب المزيد من البركة في كل مرة تقف فيها من الانحناء في الصلاة.","lesson":"قول (اللهم ربنا) في دعاء الرفع من الركوع يجلب المزيد من البركة في كل صلاة."},{"id":208,"text":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ، لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","title":"دعاء الرفع من الركوع (رقم ٢)","source":"مسلم: ٤٧٨","reflection":"دعاء الرفع من الركوع يذكرنا بأن الله وحده هو من يعطي ويمنع، مما يملأ صلواتنا بالثناء والتوكل، ويجعل كل صلاة مباركة ومقبولة عند الله إن شاء الله.","lesson":"دعاء الرفع من الركوع يظهر الثقة الكاملة في قوة الله وهباته."},{"id":209,"text":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ مُبَارَكًا عَلَيْهِ كَمَا يُحِبُّ رَبُّنَا وَيَرْضَى","title":"دعاء الثناء على الله (بعد الركوع)","source":"حسن (الألباني). سنن النسائي: ٩٣١","reflection":"يملأ دعاء الرفع من الركوع صلاتك بالكلمات التي يحبها الله، مما يجلب المزيد من البركة ويجعل خطوات صلاتك أكثر إرضاءً له في كل مرة تثني عليه فيها في الصلاة.","lesson":"الحمد لله بعد الركوع يجلب الثناء الذي يحبه الله ويقبله."},{"id":213,"text":"سُبْحَانَ رَبِّيَ الْأَعْلَى","title":"دعاء السجود (سبحان ربي الأعلى)","source":"مسلم: ٧٧٢","reflection":"دعاء السجود هذا يقربك من الله، ويملأ سجودك بالثناء، ويجعل صلاتك أحب إلى الله في كل مرة تقول فيها (سبحان ربي الأعلى).","lesson":"(سبحان ربي الأعلى) في السجود تجلب المزيد من البركة والسكينة في كل سجدة."},{"id":214,"text":"سُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ","title":"دعاء السجود","source":"سنده حسن (شعيب الأرناؤوط). أبو داود: ٨٧٠","reflection":"استشعر القرب من الله وارفع إيمانك بقول دعاء السجود في كل سجدة، حيث يجلب هذا الدعاء القصير البركة والسكينة لقلب كل مسلم.","lesson":"قول (سبحان ربي الأعلى) في السجود يجلب البركة ويجعل الصلاة أقرب للقبول."},{"id":215,"text":"اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ كُلَّهُ دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَّتَهُ وَسِرَّهُ","title":"دعاء السجود (اللهم اغفر لي)","source":"مسلم: ٤٨٣","reflection":"اطلب من الله المغفرة التامة في كل سجود بهذا الدعاء القوي، واجعل قلبك يجد الطمأنينة والأمل بينما تدعو طلبا للرحمة وصحيفة أعمال نقية.","lesson":"(اللهم اغفر لي ذنبي) في السجود يساعد على محو جميع أنواع الذنوب للمسلمين."},{"id":216,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوْذُ بِكَ مِنْكَ، لَا أُحْصِيْ ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ","title":"دعاء السجود (الدعاء عند السجود)","source":"مسلم: ٤٨٦، صحيح (الألباني). الترمذي: ٣٥٦٦","reflection":"جد الطمأنينة والأمل بقول هذا الدعاء في السجود، حيث يجلب رحمة الله، ويبقي القلب متواضعاً، ويساعد كل مسلم على البقاء في مأمن من الغضب والعقاب.","lesson":"دعاء (اللهم إني) في السجود يجلب رضا الله ويدفع غضبه."},{"id":217,"text":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِيْ نُورًا، وَفِي سَمْعِيْ نُورًا، وَفِي بَصَرِيْ نُورًا، وَعَنْ يَمِيْنِيْ نُورًا، وَعَنْ شِمَالِيْ نُورًا، وَأَمَامِيْ نُورًا، وَخَلْفِي نُورًا، وَفَوْقِيْ نُورًا، وَتَحْتِيْ نُورًا، وَاجْعَلْ لِي نُورًا (وَاجْعَلْنِيْ نُورًا)، وَاجْعَلْ فِي نَفْسِي نُورًا، (وَفِي عَصَبِيْ نُورًا، وَفِي لَحْمِي نُورًا، وَفِي دَمِيْ نُورًا، وَفِي شَعْرِيْ نُورًا، وَفِي بَشَرِيْ نُورًا)، اَللَّهُمَّ أَعْطِنِيْ نُورًا","title":"دعاء الرفع من الركوع (دعاء النور)","source":"صحيح البخاري: ٦٣١٦، صحيح مسلم: ٧٦٣","reflection":"اسأل الله النور في كل جزء من حياتك بهذا الدعاء بعد الركوع، داعيا قلبك وأفعالك تشرق بنوره وهداه في كل خطوة تخطوها.","lesson":"دعاء النور يملأ القلب والوجه بالنور ويجلب الطمأنينة في العمل."},{"id":219,"text":"سُبُّوحٌ، قُدُّوسٌ، رَبُّ الْمَلَائِكَةِ وَالرُّوحِ","title":"دعاء السجود (سبوح قدوس رب الملائكة والروح)","source":"صحيح (الألباني). أبو داود: ٨٧٢","reflection":"دعاء السجود هذا يقرب المسلم من الله، ويملأ القلب بالسكينة، ويذكرنا بعظمته ورحمته في أكثر أجزاء الصلاة تواضعا.","lesson":"تقترب رحمة الله عندما يقول المسلم (سبوح قدوس) في السجود."},{"id":220,"text":"اَللَّهُمَّ لَكَ سَجَدْتُ وَلَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَصَوَّرَهُ، فَأَحْسَنَ صُوْرَتَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ","title":"دعاء السجود (اللهم لك سجدت وبك آمنت)","source":"صحيح (الألباني). النسائي: ١١٢٦","reflection":"يساعد هذا الدعاء في السجود المسلم على إظهار التوكل الكامل على الله، مما يجعل كل سجدة في الصلاة ذات معنى أكبر ويملأ القلب شكرا على نعمه ورحمته.","lesson":"(اللهم) في السجود تظهر عمل المسلم وتوكله الكامل على تدبير الله."},{"id":221,"text":"سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ","title":"دعاء السجود","source":"حسن (الألباني). أبو داود: ٨٧٣","reflection":"دعاء السجود هذا يذكر المسلمين بعظمة الله وقدرته، مما يجعل كل سجدة في الصلاة أعمق ويساعد القلوب على الشعور بالقرب من مالك كل شيء.","lesson":"قول هذا الدعاء في السجود يساعد المسلمين على تذكر قوة الله الكاملة وسيطرته."},{"id":222,"text":"رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي","title":"الدعاء بين السجدتين","source":"صحيح (الألباني). أبو داود: ٨٧٤","reflection":"هذا الدعاء بين السجدتين يساعد المسلم على طلب المغفرة من الله، مما يجعل الصلاة أكثر خشوعا ويملأ القلب بالأمل في الرحمة وصحيفة أعمال نقية.","lesson":"دعاء (رب اغفر لي) يقرب مغفرة الله ويمحو الذنوب الصغرى."},{"id":223,"text":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي","title":"الدعاء بين السجدتين (اللهم اغفر لي وارحمني واهدني وارزقني)","source":"صحيح (الألباني). الترمذي: ٢٨٤، حسن (الألباني). أبو داود: ٨٥٠","reflection":"يساعد هذا الدعاء بين السجدتين المسلم على أن يسأل الله المغفرة والرحمة والعافية والهداية والرزق، مما يجعل كل صلاة مليئة بالأمل والبركة من الله.","lesson":"دعاء (اللهم اغفر لي) يجلب مغفرة الله ويغمر القلب برحمته."},{"id":225,"text":"اَللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا، وَضَعْ عَنِّي بِهَا وِزْرًا، وَاجْعَلْهَا لِي عِنْدَكَ ذُخْرًا، وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ","title":"دعاء سجود التلاوة في القرآن","source":"حسن (الألباني). الترمذي: ٥٧٩","reflection":"دعاء السجود هذا بعد آية السجدة في القرآن يجلب الأجر، ويمحو الذنوب، ويساعد المسلم على التقرب إلى الله، مما يجعل كل سجدة في تلاوة القرآن ذات معنى ومقبولة.","lesson":"يعطي الله الأجر على كل سجدة في تلاوة القرآن مع دعاء السجود هذا."},{"id":226,"text":"سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ","title":"دعاء سجود التلاوة في الليل","source":"حسن (الألباني). الترمذي: ٥٨٠","reflection":"يساعد دعاء سجود التلاوة في صلاة التهجد المسلم على تذكر قوة الله، ويجلب المغفرة، ويجعل صلاة الليل أكثر تميزا بالإيمان الصادق والبركة في كل سجدة.","lesson":"تُذكر قوة الله عندما يستخدم المسلمون دعاء السجود هذا في التهجد."},{"id":227,"text":"سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ، فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ","title":"دعاء سجود التلاوة","source":"صحيح (الألباني). الترمذي: ٣٤٢٥، سورة المؤمنون ٢٣:١٤","reflection":"دعاء سجود التلاوة هذا يثني على الله كأحسن الخالقين، ويجلب البركة، ويساعد المسلم على تذكر قوته ورحمته في كل سجدة بعد قراءة القرآن.","lesson":"يُثنى على عظمة الله بدعاء السجود هذا من سورة المؤمنون في القرآن."},{"id":228,"text":"اَلتَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ، وَالطَّيِّبَاتُ، اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","title":"دعاء التشهد (التحيات لله والصلوات)","source":"البخاري: ٧٣٨١","reflection":"يُحضر دعاء التشهد هذا في الصلاة الطمأنينة، ويؤكد الإيمان، ويربط المسلم بالله ونبيه، مما يجعل كل تشهد في الصلاة مليئاً بالبركة والقبول.","lesson":"(التحيات لله والصلوات) تؤكد وحدانية الله والإيمان الصادق."},{"id":229,"text":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَّعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيْمَ وَعَلَى آلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ اَللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَّعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيْمَ وَعَلَى آلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ","title":"الصلوات الإبراهيمية","source":"البخاري: ٣٣٧٠","reflection":"الصلوات الإبراهيمية تجلب البركة والرحمة للنبي محمد وآله، وتزيد من البركة في حياة المسلم، وهي دعاء خاص بعد التشهد في كل صلاة للقبول والأجر.","lesson":"(اللهم صل على محمد) تجلب رحمة الله على النبي وآله."},{"id":230,"text":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيْمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَجِيْدٌ","title":"الدعاء بعد التشهد (الصلوات الإبراهيمية)","source":"البخاري: ٣٣٦٩","reflection":"هذا الدعاء بعد التحيات يجلب البركة والسلام، ويربط القلوب بالنبي محمد صلى الله عليه وسلم وآله، ويجلب رحمة الله لمن يقرؤه في صلاتهم كل يوم.","lesson":"(اللهم صل على محمد) تجلب البركة والرحمة في صلاة المسلم."},{"id":231,"text":"اَللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا وَأَصْلِحْ ذَاتَ بَيْنِنَا وَاهْدِنَا سُبُلَ السَّلَامِ وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّوْرِ وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ وَاجْعَلْنَا شَاكِرِيْنَ لِنِعْمَتِكَ مُثْنِيْنَ بِهَا قَابِلِيْهَا وَأَتِمَّهَا عَلَيْنَا","title":"الدعاء المأثور ١ (اللهم ألف بين قلوبنا)","source":"ضعيف (الألباني). أبو داود: ٩٦٩","reflection":"هذا الدعاء المأثور يؤلف بين القلوب، ويساعد العائلات والأصدقاء على البقاء مقربين، ويسأل الله السلام والنور والبركة في كل جزء من حياة المسلم، ظاهرا وباطنا.","lesson":"(اللهم ألف بين قلوبنا) تحافظ على قوة الحب والوحدة في الأسر المسلمة."},{"id":232,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ","title":"الدعاء المأثور ٢ (دعاء الحماية من عذاب النار)","source":"مسلم: ٥٨٨","reflection":"هذا الدعاء المأثور يسأل الله أن يحفظ المسلمين من جهنم، والقبر، وجميع الفتن الكبرى، مما يجعله دعاء حماية قوي لعمل وإيمان كل مؤمن يومياً.","lesson":"دعاء الحماية من الشر يحفظ المسلمين من عذاب جهنم."},{"id":233,"text":"اَللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ","title":"الدعاء المأثور ٣ (اللهم اغفر لي ما قدمت)","source":"مسلم: ٧٧١","reflection":"هذا الدعاء المأثور للمغفرة يساعد المسلمين على أن يسألوا الله تطهير جميع الذنوب، الخفية والظاهرة، ويجلب الأمل في المغفرة والرحمة في عمل كل مسلم وصلاته اليومية.","lesson":"(اللهم اغفر لي ما قدمت) يمحو الذنوب القديمة والجديدة من حياة المسلم."},{"id":234,"text":"اَللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِيْ ظُلْمًا كَثِيْرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِيْ إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","title":"الدعاء المأثور ٤ (اللهم إني ظلمت نفسي)","source":"البخاري: ٨٣٤","reflection":"هذا الدعاء المأثور في الصلاة يساعد المسلمين على الاعتراف بأخطائهم وسؤال الله مغفرته ورحمته، مما يجعل القلوب رقيقة ويجلب الأمل في المغفرة في كل صلاة.","lesson":"(اللهم إني ظلمت نفسي) يجلب مغفرة الله للذنوب الكبيرة والصغيرة."},{"id":236,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوْذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوْذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا","title":"الدعاء المأثور ٦ (اللهم إني أسألك من الخير)","source":"صحيح (الألباني). ابن ماجه: ٣٨٤٦","reflection":"هذا الدعاء المأثور يساعد المسلم على أن يسأل الله التوفيق في كل خير والسلامة من كل شر، مما يجعل القلب قوياً في العمل ويجلب الأمل في الجنة والبركة في كل جزء من الحياة.","lesson":"يعطي الله المسلم البركة ويبعد عنه كل شر بالدعاء المأثور."},{"id":237,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَحْـيَا وَالْمَمَاتِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ","title":"دعاء الحماية من عذاب القبر والنار والدجال","source":"البخاري: ٨٣٢","reflection":"هذا الدعاء المأثور يحفظ المسلم من أشد الفتن ويجلب عون الله في كل شؤون الحياة، طالبًا البركة والمغفرة والحماية من كل شر وفتنة.","lesson":"يحفظ الله المسلم من عذاب القبر بدعاء الحماية هذا."},{"id":238,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيْحِ الدَّجَّالِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْمَأْثَمِ وَمِنَ الْمَغْرَمِ","title":"الدعاء في آخر الصلاة (اللهم إني أعوذ بك)","source":"مسلم: ١/٤١٢","reflection":"هذا الدعاء المأثور يساعد المسلم في الحصول على حماية الله من كل فتنة كبرى، ويحافظ على القلب آمناً من جهنم، والدجال، وعبء الذنوب والديون بعد كل صلاة.","lesson":"ينجي الله المسلم من عذاب جهنم بهذا الدعاء بعد الصلاة."},{"id":239,"text":"اَللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ","title":"الدعاء المأثور ٧ (اللهم أعني على ذكرك)","source":"صحيح (الألباني). أبو داود: ١٥٢٢","reflection":"يساعد هذا الدعاء المأثور المسلم على إبقاء الله قريبًا في كل عمل، مما يجعل القلب ممتلئًا بالشكر، وقويًا في ذكر الله، ومستعدًا دائمًا للعبادة الصالحة بعد كل صلاة.","lesson":"يعطي الله المسلم القوة لذكر الله ويحافظ على رقة القلب بهذا الدعاء."},{"id":240,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوْذُ بِكَ مِنْ أَنْ نُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ","title":"الدعاء المأثور ٨ (اللهم إني أعوذ بك من البخل)","source":"البخاري: ٦٣٧٤","reflection":"يساعد هذا الدعاء المأثور المسلم على البقاء آمنا من سيئات الدنيا، طالبًا من الله البركة، والشجاعة، والحماية من عذاب القبر وكل فتنة في الحياة.","lesson":"يبعد الله المسلم عن البخل ويعطيه البركة بدعاء الحماية هذا."},{"id":241,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوْذُ بِكَ مِنَ النَّارِ","title":"دعاء للجنة (اللهم إني أسألك الجنة)","source":"صحيح (الألباني). ابن ماجه: ٣٨٤٦","reflection":"يساعد دعاء الجنة هذا المسلم على أن يسأل الله أفضل مكان في الآخرة، مما يبقي القلب مليئاً بالأمل والبركة والسلامة من جهنم في كل جزء من الحياة.","lesson":"يعطي الله المسلم الأمل في جنة الفردوس بهذا الدعاء البسيط للجنة."},{"id":242,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا أَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","title":"الدعاء المأثور ٩ (اللهم إني أسألك يا الله بأنك)","source":"صحيح (الألباني). النسائي: ١٣٠١","reflection":"يساعد هذا الدعاء المأثور المسلم على طلب المغفرة من الله من خلال مناداته بأسمائه الخاصة، مما يجلب البركة والرحمة والأمل في المغفرة في كل جزء من الحياة.","lesson":"يغفر الله الذنوب ويمنح المغفرة بهذا الدعاء المأثور بعد الصلاة."},{"id":243,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلاَّ أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ","title":"الدعاء المأثور ١٠","source":"صحيح (الألباني). النسائي: ١٣٠٠","reflection":"يساعد هذا الدعاء المأثور المسلم على دعوة الله بأسمائه الحسنى، مما يجلب البركة والأمل والقوة في كل عمل من خلال الثناء عليه يا حي يا قيوم ويا ذا الجلال والإكرام.","lesson":"يعطي الله البركة ويستجيب الدعاء عندما يٌنادى بـ (يا حي يا قيوم)."},{"id":244,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي اَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ","title":"الدعاء المأثور ١١ (اللهم إني أسألك بأنك أنت الله)","source":"صحيح (الألباني). أبو داود: ١٤٩٣","reflection":"يساعد هذا الدعاء المأثور المسلم على مناداة الله بأسمائه الخاصة، مما يجلب البركة والإيمان القوي والأمل لكل عمل بتذكره أنه الأحد، الصمد، وأنه لا مثيل له.","lesson":"يستجيب الله الدعاء عندما يدعوه المسلم بـ (لا إله إلا أنت) و (اللهم)."},{"id":245,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، الْمَنَّانُ، يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوْذُ بِكَ مِنَ النَّارِ","title":"الدعاء المأثور ١٢","source":"صحيح (الألباني). أبو داود: ١٤٩٣-١٤٩٥","reflection":"هذا الدعاء المأثور الجميل يسأل الله الجنة والحماية من جهنم، مستخدماً أسماءه المباركة مثل (يا حي يا قيوم) و(يا ذا الجلال والإكرام)، مما يجلب الأمل والطمأنينة لكل قلب مسلم.","lesson":"يمنح الله الجنة للمسلم الذي يدعو بهذا الدعاء المأثور بإيمان."},{"id":246,"text":"اَللَّهُ أَكْبَرُ كَبِيْرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا","title":"دعاء في الصلاة (الله أكبر كبيرا والحمد لله كثيرا)","source":"مسلم: ٦٠١","reflection":"هذا الدعاء في الصلاة يملأ القلب بعظمة الله والثناء عليه، مما يجعل صلاة كل مسلم تبدأ بالبركة والسكينة، ويساعد على إبقاء العقل مركزًا على الله من البداية إلى النهاية.","lesson":"(الله أكبر كبيرا) في دعاء الاستفتاح ترفع القلب بعظمة الله في الصلاة."},{"id":247,"text":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا","title":"دعاء ما بعد صلاة الفجر (اللهم إني أسألك علما)","source":"صحيح (الألباني). ابن ماجه: ٩٢٥","reflection":"هذا الدعاء بعد صلاة الفجر يقرب المسلم من رحمة الله، طالباً العلم النافع، والرزق الطيب، والعمل المتقبل، مما يجعل كل صباح يبدأ بالأمل والبركة من صلاة الفجر.","lesson":"(اللهم إني أسألك علما نافعا) في دعاء الفجر يجلب العلم النافع للمسلمين."},{"id":248,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","title":"دعاء ما بعد الفجر والمغرب ١","source":"حسن (الألباني). الترمذي: ٣٥٣٤","reflection":"هذا الدعاء بعد صلاة الفجر والمغرب يذكر كل مسلم بوحدانية الله، وقوته، ورحمته، مما يقوي القلب بالشهادة ويملأ اليوم والليلة بالبركة والسلام.","lesson":"(لا إله إلا الله) في هذا الدعاء بعد صلاة الفجر تحافظ على الإيمان قويا ونقيا."},{"id":249,"text":"اَللَّهُمَّ أَجِرْنِيْ مِنَ النَّارِ","title":"دعاء ما بعد الفجر والمغرب ٢ (اللهم أجرني من النار)","source":"حسن (ابن حجر). الفتوحات الربانية: ٣/٦٩","reflection":"هذا الدعاء بعد صلاة المغرب والفجر يسأل الله الحماية من جهنم، مما يجعل صباح كل مسلم ومسائه مليئًا بالأمل والسلامة ورحمة الله في الحياة اليومية.","lesson":"(اللهم أجرني من النار) في دعاء المغرب يحمي المسلم من جهنم."},{"id":250,"text":"أَسْتَغْفِرُ اللَّهَ","title":"دعاء ما بعد الصلاة (أستغفر الله)","source":"صحيح مسلم: ٥٩١","reflection":"يساعد دعاء (أستغفر الله) بعد الصلاة كل مسلم على طلب مغفرة الله، مما يطهر القلب ويجلب البركة للعمل اليومي، مع إبقاء الروح قريبة من رحمة الله ولطفه.","lesson":"(أستغفر الله) بعد الصلاة تمحو صغائر الذنوب والأخطاء من العمل."},{"id":251,"text":"اَللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","title":"دعاء ما بعد الصلاة (اللهم أنت السلام ومنك السلام)","source":"مسلم: ٥٩١","reflection":"هذا الدعاء بعد الصلاة يملأ القلب بالسلام من الله، ويذكر كل مسلم بأن السلامة الحقيقية والبركة لا تأتي إلا منه، ويجلب التكريم بمناداة (يا ذا الجلال والإكرام) بعد كل صلاة.","lesson":"يجلب دعاء (اللهم أنت السلام) في الدعاء بعد الصلاة سلاما حقيقيا لقلب المسلم."},{"id":252,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِىَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","title":"دعاء ما بعد التسليم","source":"البخاري: ٨٤٤","reflection":"هذا الدعاء بعد السلام يذكر كل مسلم أن كل القوة والعطايا من الله وحده، مما يقوي القلب في التوحيد، ويملأ الحياة اليومية بالبركة والأمل، ويزيد الثقة والتوكل في تدبير الله.","lesson":"(لا إله إلا الله وحده لا شريك له) في الدعاء بعد السلام تحافظ على نقاء الإيمان."},{"id":253,"text":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيْرٌ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ لَا إِلَهَ إِلَّا اللَّهُ وَلَا نَعْبُدُ إِلَّا إِيَّاهُ لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِيْنَ لَهُ الدِّيْنَ وَلَوْ كَرِهَ الْكَافِرُوْنَ","title":"دعاء ما بعد التسليم في الصلاة","source":"مسلم: ٥٩٤","reflection":"هذا الدعاء بعد التسليم في الصلاة يملأ القلب بالتوحيد والثقة والإيمان الخالص، ويذكر كل مسلم بأن كل القوة والثناء والنعم تأتي من الله وحده، ويحافظ على سلامة الروح بالذكر اليومي.","lesson":"(لا إله إلا الله وحده لا شريك له) في الدعاء بعد الصلاة تبقي الإيمان قويا."},{"id":257,"text":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَاللَّهُ أَكْبَرُ","title":"ذكر قوي بعد الصلاة","source":"مسلم: ١/٤١٨، رقم ٥٩٧","reflection":"هذا الذكر بعد الصلاة يملأ القلب بالطمأنينة ويقرب رحمة الله، مما يجعل كل مسلم يشعر ببركات سبحان الله والحمد لله والله أكبر في الحياة اليومية.","lesson":"سبحان الله والحمد لله مع الله أكبر تجعل الإيمان قويا بعد كل صلاة."},{"id":258,"text":"رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ (تَجْمَعُ) عِبَادَكَ","title":"دعاء في آخر الصلاة","source":"مسلم: ٧٠٩","reflection":"هذا الدعاء في نهاية الصلاة يسأل الله السلامة من عذابه ويجلب الأمل لكل مسلم يبتغي المغفرة والرحمة يوم يقف الناس جميعًا بين يديه.","lesson":"تقترب رحمة الله من المسلم الذي يدعو بعد الصلاة بيقين."},{"id":259,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ وَعَذَابِ الْقَبْرِ","title":"دعاء في آخر الصلاة","source":"صحيح (الألباني). النسائي: ٥٤٦٥","reflection":"هذا الدعاء في نهاية الصلاة يسأل الله الحماية من الكفر، والفقر، وعذاب القبر، مما يمنح كل مسلم أملاً في السلامة والطمأنينة في الدنيا والآخرة.","lesson":"(اللهم إني أعوذ بك) تحفظ المسلم من الكفر وضعف الإيمان بعد الصلاة."},{"id":260,"text":"اَللَّهُمَّ أَعِنِّى عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","title":"دعاء ما بعد الصلاة (اللهم أعني على ذكرك وشكرك)","source":"صحيح (الألباني). أبو داود: ١٥٢٢","reflection":"دعاء ما بعد الصلاة هذا يسأل الله العون في ذكره، وشكره، وأداء العبادة على أكمل وجه، مما يملأ قلب كل مسلم بالذكر والشكر بعد كل صلاة.","lesson":"(اللهم أعني على ذكرك وشكرك) تجلب البركة في عمل كل مسلم."},{"id":261,"text":"اَللَّهُمَّ غْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ","title":"دعاء ما بعد الصلاة","source":"[١] مسلم: ٧٧١\n[٢] صحيح (الألباني). أبو داود: ١٥٠٩","reflection":"يسأل هذا الدعاء بعد الصلاة الله أن يغفر كل ذنب، سواء كان خفيا أو علنيا، ويجلب الأمل في الرحمة لكل مسلم يريد قلبا نقيا ومغفرة من الله بعد كل صلاة.","lesson":"(اللهم اغفر لي ما قدمت) تساعد المسلم في الحصول على المغفرة عن جميع أخطاء الماضي."},{"id":262,"text":"اَللَّهُمَّ أَصْلِحْ لِي دِيْنِيَ الَّذِي جَعَلْتَهُ عِصْمَةَ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي جَعَلْتَ فِيهَا مَعَاشِيْ، اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِعَفْوِكَ مِنْ نِقْمَتِكَ، وَأَعُودُ بِكَ مِنْكَ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","title":"دعاء في آخر الصلاة","source":"حسن (ابن حجر). الفتوحات الربانية: ٣/٧١","reflection":"يسأل هذا الدعاء في آخر الصلاة الله أن يصلح الدين والدنيا، مجلبًا رحمته وعونه لكل مسلم يريد حياة طيبة وإيمانًا قويًا بعد كل صلاة.","lesson":"(اللهم لا مانع لما أعطيت) تحفظ الرزق وتجلب البركة في الحياة اليومية."},{"id":263,"text":"اَللَّهُمَّ بِكَ أُحَاوِلُ وَبِكَ أُقَاتِلُ وَبِكَ أَصَاوِلُ","title":"دعاء ما بعد الصلاة","source":"صحيح (الألباني). الدارمي: ٢/٢١٧","reflection":"دعاء ما بعد الصلاة هذا يطلب من الله المساعدة في كل صراع، مما يجعل المسلم قويا وشجاعا بدعمه في كل جزء من الحياة.","lesson":"الدعاء به يعطي المسلم القوة لمواجهة الصعاب والفوز بعون الله."},{"id":264,"text":"اَللَّهُمَّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْم (التَّوَّابُ الْغَفُورُ)","title":"دعاء ما بعد الصلاة (اللهم اغفر لي وارحمني وتب علي)","source":"صحيح (الألباني). الصحيحة: ٥٥٦، أحمد: ٥٥٦٤","reflection":"هذا الدعاء بعد الصلاة يطلب من الله المغفرة والرحمة، مما يساعد كل مسلم في العثور على الأمل والقلب النقي بعد كل صلاة من خلال الثقة بلطف الله وقدرته على قبول التوبة.","lesson":"قول (رب اغفر لي وارحمني) يجلب رحمة الله ويمسح الذنوب القديمة بعد الصلاة."},{"id":265,"text":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَخَطَايَايَ كُلَّهَا اَللَّهُمَّ أَنْعِشْنِيْ وَاجْبُرْنِيْ وَاهْدِنيْ لِصَالِحِ الْأَعْمَالِ وَالْأَخْلَاقِ فَإِنَّهُ لَا يَهْدِيْ لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ","title":"دعاء ما بعد الصلاة","source":"حسن (الألباني). صحيح الجامع: ١٢٦٦","reflection":"دعاء ما بعد الصلاة هذا يساعد المسلم على سؤال الله المغفرة والأخلاق الحسنة، مما يجعل كل صلاة وقتا لطلب رحمته وهدايته لأعمال أفضل وقلب نقي.","lesson":"(اللهم) في دعاء ما بعد الصلاة هذا يجلب المغفرة لجميع الأخطاء والذنوب."},{"id":266,"text":"اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ وَوَسِّعْ لِي فِي دَارِيْ وَبَارِكْ لِي فِي رِزْقِيْ","title":"دعاء ما بعد الصلاة","source":"حسن (الألباني). صحيح الجامع: ١٢٦٥","reflection":"هذا الدعاء بعد الصلاة يساعد المسلم على سؤال الله المغفرة، والبركة في الرزق، والمنزل الآمن الهادئ، مما يجعل كل صلاة وقتًا لطلب رحمته وبركاته للحياة اليومية والأسرة.","lesson":"(اللهم) في دعاء ما بعد الصلاة هذا تجلب مغفرة الله لكل ذنب."},{"id":267,"text":"اَللَّهُ اَكْبَرُ","title":"الذكر بعد الصلاة","source":"","reflection":"قول (الله أكبر) بعد الصلاة يذكر المسلم بأن الله هو الأعظم، مما يجلب الطمأنينة للقلب ويجعل كل صلاة أقوى بقوة التكبير والإيمان الصادق.","lesson":"التكبير بعد الصلاة يرفع القلب ويبقي عظمة الله في العقل."},{"id":268,"text":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ","title":"دعاء ما بعد الصلاة","source":"مسلم: ٢٧٢٦","reflection":"قول (سبحان الله وبحمده) بعد الصلاة يملأ القلب بالثناء على الله، ويقوي كل صلاة ويجلب رضاه ورحمته وبركاته في الحياة اليومية.","lesson":"(سبحان الله وبحمده) في التسبيح بعد الصلاة تجلب رضا الله ورحمته."},{"id":273,"text":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلَهَ غَيْرُكَ","title":"دعاء استفتاح صلاة التهجد (سبحانك اللهم)","source":"صحيح (الألباني). أبو داود: ٧٧٥","reflection":"دعاء استفتاح صلاة التهجد يملأ القلب بالثناء على الله، مما يجعل قيام الليل أكثر قوة ويجلب البركة والرحمة والقرب من الله في كل تهجد.","lesson":"(سبحانك اللهم) في صلاة التهجد تجلب بركة الله ورحمته."},{"id":274,"text":"سُبْحَانَ الْمَلِكِ الْقُّدُّوْسِ","title":"دعاء ما بعد صلاة الوتر (سبحان الملك القدوس)","source":"صحيح (الألباني). أبو داود رقم ١٤٣٠؛ النسائي رقم ١٦٩٩، ١٧٠١","reflection":"قول (سبحان الملك القدوس) بعد صلاة الوتر يملأ القلب بعظمة الله، مما يجعل ختام صلاة الليل مميزا ويجلب السلام والبركة والنقاء لكل مسلم.","lesson":"(سبحان الملك القدوس) في الدعاء بعد صلاة الوتر تجلب طهارة الله والثناء عليه."},{"id":275,"text":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُــوذُ بِكَ مِنْكَ، لَا أُحْصِيْ ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ","title":"دعاء ما بعد صلاة الوتر (اللهم إني أعوذ برضاك)","source":"","reflection":"دعاء ما بعد صلاة الوتر هذا يساعد المسلم على طلب رضا الله ومغفرته، مما يجعل نهاية صلاة الليل وقتا للحماية والرحمة والثناء الصادق على الله.","lesson":"الدعاء بعد صلاة الوتر يسأل الله الحماية من غضبه وعقابه."},{"id":276,"text":"رَبُّ الْمَلَائِكَةِ وَالرُّوحِ","title":"دعاء ما بعد صلاة الوتر (رب الملائكة والروح)","source":"","reflection":"يعمل هذا الدعاء بعد صلاة الوتر على تذكير المسلم بقدرة الله على جميع الملائكة وجبريل، مما يجعل نهاية صلاة الليل مليئة بالثناء والبركة والتقرب إلى رب الملائكة.","lesson":"الدعاء بعد صلاة الوتر بـ (رب الملائكة والروح) يظهر عظمة الله."},{"id":278,"text":"اَللَّهُمَّ اهْدِنِيْ فِيمَنْ هَدَيْتَ، وَعَافِنِيْ فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِيْ شَرَّ مَا قَضَيْتَ فَإِنَّكَ تَقْضِيْ وَلَا يُقْضَى عَلَيْكَ وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ تَبارَكْتَ رَبَّنَا وَتَعَالَيْتَ","title":"دعاء الوتر (دعاء القنوت)","source":"صحيح (الألباني). أبو داود: ١٤٢٥","reflection":"دعاء الوتر، المعروف بـ (دعاء القنوت)، يجلب هداية الله، وحمايته، وبركته، ويقوي صلاة الليل ويملأ القلب بالأمل والسلامة والبركات الحقيقية من الله.","lesson":"دعاء الوتر يسأل الله الهداية ويبقي المسلم على الطريق المستقيم."},{"id":279,"text":"رَبِّ أَعِنِّيْ وَلَا تُعِنْ عَلَيَّ وَانْصُرْنِيْ وَلَا تَنْصُرْ عَلَيَّ وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ وَاهْدِنِيْ وَيَسِّرِ الْهُدَى لِي (إِلَيَّ) وَانْصُرْنِيْ عَلَى مَنْ بَغَى عَلَيَّ رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا لَكَ ذَكَّارًا لَكَ رَهَّابًا لَكَ مِطْوَاعًا لَكَ مُخْبِتًا إِلَيْكَ أَوَّاهًا مُنِيْبًا رَبِّ تَقَبَّلْ تَوْبَتِيْ وَاغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِيْ وَثَبِّتْ حُجَّتِيْ وَسَدِّدْ لِسَانِيْ وَاهْدِ قَلْبِيْ وَاسْلُلْ سَخِيْمَةَ صَدْرِيْ","title":"دعاء القنوت (رب أعني ولا تعن علي)","source":"صحيح (الألباني). الترمذي: ٣٥٥١","reflection":"دعاء القنوت هذا يقرب المسلم من عون الله ورحمته، طالبا القوة والهداية والمغفرة في كل جزء من الحياة، وخاصة في أوقات الحاجة والصعاب.","lesson":"يعطي الله القوة والعون لمن يدعو بدعاء القنوت بإيمان."},{"id":280,"text":"اَللَّهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَى عَذَابَكَ، إِنَّ عَذَابَكَ بِالْكَافِرِينَ مُلْحَقٌ، اَللَّهُمَّ إِنَّا نَسْتَعِينُكَ، وَنَسْتَغْفِرُكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَلَا نَكْفُرُكَ، وَنُؤْمِنُ بِكَ، وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفُرُكَ","title":"دعاء القنوت (اللهم إنا نستعينك)","source":"صحيح (الألباني). إرواء الغليل: ٢/١٧٠، البيهقي: السنن الكبرى - ٢/٢١١","reflection":"يساعد دعاء القنوت هذا في صلاة الوتر المسلم على إظهار الإيمان الحقيقي، وطلب رحمة الله، والبحث عن المغفرة، مما يجعل القلب رقيقا ومليئا بالأمل في كل صلاة وشدة.","lesson":"قول (اللهم إنا نستعينك) يجلب عون الله ومغفرته في صلاة الوتر."},{"id":282,"text":"اَللَّهُ أَكْبَرُ","title":"عند الاستيقاظ لصلاة التهجد (ذكر ودعاء)","source":"حسن (الألباني). أبو داود: ٧٦٦","reflection":"قول (الله أكبر) قبل صلاة التهجد يملأ القلب بالقوة ويساعد المسلم على تذكر عظمة الله في هدوء الليل، مما يجعل كل تهجد أكثر تميزا ومليئا بالبركة.","lesson":"قول (الله أكبر) قبل التهجد يقرب القلب من عظمة الله."},{"id":284,"text":"وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَىٰ مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ﴿١٣٥﴾ أُولَٰئِكَ جَزَاؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ الْعَامِلِينَ ﴿١٣٦﴾","title":"دعاء التوبة بعد الذنب (صلاة ركعتين)","source":"صحيح (الألباني). أبو داود: ١٥٢١","reflection":"يساعد دعاء التوبة هذا بعد المعصية المسلم على الرجوع إلى الله بقلب طاهر، طالبا المغفرة والرحمة، ويجلب الأمل في الجنة وبداية جديدة بعد كل خطأ.","lesson":"دعاء التوبة يجلب مغفرة الله ويمسح الذنوب القديمة بسرعة."},{"id":285,"text":"اَللَّهُمَّ اغْفِرْ لَهُ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِيْنَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِيْنَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ","title":"دعاء للميت","source":"مسلم: ٩٢٠","reflection":"يجلب دعاء الميت هذا الرجاء والرحمة لمن توفي، طالبا من الله أن يغفر له، وينير قبره، ويرفع مكانته في المهديين، مع البركة لأهله.","lesson":"الدعاء للميت يسأل الله أن يغفر ويرفع درجات الشخص."},{"id":287,"text":"بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُوْلِ اللَّهِ (ﷺ)","title":"دعاء إدخال الميت القبر","source":"","reflection":"يجلب هذا الدعاء للقبر السلام والبركة عند وضع الميت، اتباعا للسنة وطلبا من الله أن يجعل الدفن سهلا ومليئا بالرحمة لمن في القبر.","lesson":"(بسم الله) عند الدفن تحفظ القبر آمنا باسم الله وحمايته."},{"id":288,"text":"بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُوْلِ اللَّهِ","title":"دعاء إدخال الميت القبر","source":"","reflection":"يجلب دعاء الجنازة هذا الراحة والبركة عند إدخال الجسد في القبر، متبعا هدي رسول الله وسائلين الله الرحمة والحماية للميت.","lesson":"(بسم الله) عند الدفن تمنح القبر الأمان والسلام باسم الله."},{"id":289,"text":"بِسْمِ اللَّهِ وَفِي سَبِيلِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ","title":"دعاء إدخال الميت القبر","source":"","reflection":"يجلب هذا الدعاء للميت السلام والرحمة عند وضع الجسد في القبر، اتباعا لطريق الله ورسوله، وطلبا للبركة والسلامة للميت.","lesson":"(بسم الله) عند الدفن تمنح القبر الحماية وعناية الله الخاصة."},{"id":290,"text":"اَلسَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِيْنَ وَالْمُسْلِمِيْنَ إِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُوْنَ أَسْاَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ","title":"دعاء زيارة القبور (السلام عليكم يا أهل القبور)","source":"مسلم: ٩٧٥","reflection":"يجلب دعاء زيارة القبور هذا السلام للأحياء والموتى، ويذكرنا بعودتنا إلى الله والروابط بين المسلمين حتى بعد الموت.","lesson":"يعطي الله البركة لمن يدعو بدعاء زيارة القبور بإيمان."},{"id":291,"text":"اَلسَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِيْنَ وَالْمُسْلِمِيْنَ وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِيْنَ مِنَّا وَالْمُسْتَأْخِرِيْنَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ","title":"دعاء دخول المقبرة (دعاء مسنون)","source":"","reflection":"دعاء دخول المقبرة هذا يذكر المسلمين بقصر الحياة، ويجلب الرحمة لأولئك الذين رحلوا، ويبقي القلب رقيقا يرجو عفو الله ولطفه.","lesson":"يظهر الله رحمته للمسلمين الذين يستخدمون دعاء دخول المقبرة هذا."},{"id":292,"text":"اَلسَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِيْنَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُوْنَ","title":"دعاء زيارة القبور (دعاء المقبرة)","source":"","reflection":"دعاء زيارة المقبرة هذا يجلب للقلوب السلام، ويربط المؤمنين، ويذكرنا بعودتنا إلى الله، مما يجعل كل زيارة مليئة بالأمل واللطف.","lesson":"يعطي الله السلام للموتى عندما يقول المسلمون (السلام عليكم) في المقبرة."},{"id":293,"text":"اَلسَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِيْنَ وَأَتَاكُمْ مَا تُوعَدُونَ غَدًا مُؤَجَّلُونَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ اَللَّهُمَّ اغْفِرْ لِأَهْلِ بَقِيعِ الْغَرْقَدِ","title":"دعاء زيارة قبور المسلمين (دعاء المقبرة)","source":"","reflection":"يجلب دعاء المقبرة هذا الأمل في المغفرة، ويربط القلوب بأولئك الراقدين، ويذكر كل مسلم بوعد الله والرحمة التي تنتظر جميع المؤمنين.","lesson":"يعطي الله المغفرة للموتى عندما يستخدم المسلمون دعاء المقبرة هذا."}];
